export const ADVANCED_LESSONS = [{"cap":3,"bai":1,"title":"Cuộc sống ký túc xá","grammar":[{"formula":"-아/어야 하다","meaning":"phải thực hiện hành động","usage":"Diễn tả nghĩa vụ hoặc sự cần thiết.","example":"기숙사에서는 밤 열한 시 이후에 조용히 해야 해요. → Trong ký túc xá phải giữ yên lặng sau 11 giờ đêm.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-(으)면 안 되다","meaning":"không được, không nên","usage":"Diễn tả hành động bị cấm hoặc không được phép.","example":"공용 주방을 사용한 후에는 깨끗이 정리해야 해요. → Sau khi sử dụng bếp chung phải dọn dẹp sạch sẽ.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["기숙사","ký túc xá"],["규칙","nội quy"],["공용","chung"],["주방","nhà bếp"],["관리자","người quản lý"],["조용하다","yên lặng"],["정리하다","dọn dẹp"],["초대하다","mời"],["사용하다","sử dụng"],["설명하다","giải thích"]],"samples":[{"ko":"기숙사에서는 밤 열한 시 이후에 조용히 해야 해요.","vi":"Trong ký túc xá phải giữ yên lặng sau 11 giờ đêm."},{"ko":"공용 주방을 사용한 후에는 깨끗이 정리해야 해요.","vi":"Sau khi sử dụng bếp chung phải dọn dẹp sạch sẽ."},{"ko":"친구를 초대하려면 먼저 관리자에게 물어보세요.","vi":"Muốn mời bạn đến thì hãy hỏi người quản lý trước."},{"ko":"규칙을 잘 몰랐으니 다시 한번 설명해 주시겠어요?","vi":"Tôi chưa hiểu rõ nội quy nên xin giải thích lại được không?"}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":3,"bai":2,"title":"Sắp xếp ca làm thêm","grammar":[{"formula":"-(으)ㄹ 수 있다","meaning":"có thể","usage":"Diễn tả khả năng hoặc điều kiện cho phép.","example":"수업이 끝나는 시간이 달라서 금요일에는 늦게 출근할 수 있어요. → Giờ tan học khác nhau nên thứ Sáu tôi có thể đi làm muộn.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-기 때문에","meaning":"bởi vì","usage":"Nêu nguyên nhân hoặc lý do.","example":"이번 주 토요일에 제 근무 시간을 바꿀 수 있을까요? → Thứ Bảy tuần này tôi có thể đổi ca làm không?","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["근무","làm việc theo ca"],["근무 시간","giờ làm"],["출근하다","đi làm"],["교대하다","đổi ca"],["동료","đồng nghiệp"],["시험 기간","kỳ thi"],["시간표","thời khóa biểu"],["부탁하다","nhờ"],["조정하다","điều chỉnh"],["가능하다","có thể"]],"samples":[{"ko":"수업이 끝나는 시간이 달라서 금요일에는 늦게 출근할 수 있어요.","vi":"Giờ tan học khác nhau nên thứ Sáu tôi có thể đi làm muộn."},{"ko":"이번 주 토요일에 제 근무 시간을 바꿀 수 있을까요?","vi":"Thứ Bảy tuần này tôi có thể đổi ca làm không?"},{"ko":"시험 기간이기 때문에 다음 주에는 시간을 조금 줄이고 싶어요.","vi":"Vì đang trong kỳ thi nên tuần sau tôi muốn giảm giờ làm một chút."},{"ko":"대신 일할 수 있는 동료에게 미리 부탁하겠습니다.","vi":"Tôi sẽ nhờ trước đồng nghiệp có thể làm thay."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":3,"bai":3,"title":"Khám bệnh và triệu chứng","grammar":[{"formula":"-은/는 것 같다","meaning":"có vẻ, hình như","usage":"Nói sự phỏng đoán dựa trên dấu hiệu.","example":"어제부터 목이 아프고 열이 나는 것 같아요. → Từ hôm qua tôi đau họng và hình như bị sốt.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-아/어 보다","meaning":"thử làm","usage":"Diễn tả thử thực hiện hành động.","example":"이 약을 먹어 봤지만 아직 낫지 않았어요. → Tôi đã thử uống thuốc này nhưng vẫn chưa khỏi.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["증상","triệu chứng"],["목","họng"],["열","sốt"],["기침","ho"],["진료","khám bệnh"],["처방","đơn thuốc"],["약","thuốc"],["낫다","khỏi bệnh"],["복용하다","uống thuốc"],["불편하다","khó chịu"]],"samples":[{"ko":"어제부터 목이 아프고 열이 나는 것 같아요.","vi":"Từ hôm qua tôi đau họng và hình như bị sốt."},{"ko":"이 약을 먹어 봤지만 아직 낫지 않았어요.","vi":"Tôi đã thử uống thuốc này nhưng vẫn chưa khỏi."},{"ko":"음식을 먹을 때마다 속이 불편합니다.","vi":"Mỗi lần ăn tôi đều cảm thấy khó chịu trong bụng."},{"ko":"언제 다시 병원에 와야 하는지 알려 주세요.","vi":"Xin cho biết khi nào tôi cần quay lại bệnh viện."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":3,"bai":4,"title":"Tìm thuê phòng","grammar":[{"formula":"-(으)려고 하다","meaning":"định làm","usage":"Diễn tả ý định thực hiện hành động.","example":"학교 근처에서 지낼 수 있는 방을 구하려고 해요. → Tôi định tìm phòng có thể ở gần trường.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-는 동안","meaning":"trong khi, trong suốt lúc","usage":"Chỉ khoảng thời gian một việc đang diễn ra.","example":"계약하는 동안 주의해야 할 점이 무엇인가요? → Trong lúc ký hợp đồng cần chú ý điều gì?","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["방","phòng"],["계약","hợp đồng"],["월세","tiền thuê tháng"],["보증금","tiền đặt cọc"],["집주인","chủ nhà"],["가구","đồ nội thất"],["부동산","văn phòng bất động sản"],["구하다","tìm kiếm"],["이사하다","chuyển nhà"],["조건","điều kiện"]],"samples":[{"ko":"학교 근처에서 지낼 수 있는 방을 구하려고 해요.","vi":"Tôi định tìm phòng có thể ở gần trường."},{"ko":"계약하는 동안 주의해야 할 점이 무엇인가요?","vi":"Trong lúc ký hợp đồng cần chú ý điều gì?"},{"ko":"관리비에 인터넷 요금도 포함되어 있나요?","vi":"Phí quản lý có bao gồm tiền Internet không?"},{"ko":"방을 직접 본 뒤에 결정하고 싶습니다.","vi":"Tôi muốn quyết định sau khi trực tiếp xem phòng."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":3,"bai":5,"title":"Bưu điện và chuyển phát","grammar":[{"formula":"-(으)ㄹ 때","meaning":"khi","usage":"Chỉ thời điểm hành động xảy ra.","example":"베트남으로 소포를 보낼 때 어떤 서류가 필요해요? → Khi gửi bưu kiện về Việt Nam cần giấy tờ nào?","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-아/어 주다","meaning":"làm giúp","usage":"Diễn tả việc làm gì cho người khác.","example":"깨지기 쉬운 물건이라서 조심해서 포장해 주세요. → Vì là đồ dễ vỡ nên xin gói cẩn thận.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["우체국","bưu điện"],["소포","bưu kiện"],["택배","giao hàng"],["주소","địa chỉ"],["우편번호","mã bưu chính"],["배송","giao nhận"],["보내다","gửi"],["받다","nhận"],["서류","giấy tờ"],["요금","phí"]],"samples":[{"ko":"베트남으로 소포를 보낼 때 어떤 서류가 필요해요?","vi":"Khi gửi bưu kiện về Việt Nam cần giấy tờ nào?"},{"ko":"깨지기 쉬운 물건이라서 조심해서 포장해 주세요.","vi":"Vì là đồ dễ vỡ nên xin gói cẩn thận."},{"ko":"배송이 언제 도착하는지 확인해 주시겠어요?","vi":"Anh/chị có thể kiểm tra khi nào hàng đến không?"},{"ko":"주소를 잘못 썼는데 지금 수정할 수 있을까요?","vi":"Tôi viết nhầm địa chỉ, bây giờ có sửa được không?"}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":3,"bai":6,"title":"Sự cố giao thông","grammar":[{"formula":"-느라고","meaning":"vì mải làm nên","usage":"Nêu nguyên nhân gắn với việc dành thời gian cho một hành động.","example":"버스를 기다리느라고 약속 시간에 늦었어요. → Vì đợi xe buýt nên tôi đến muộn giờ hẹn.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-는 바람에","meaning":"vì sự việc bất ngờ dẫn đến","usage":"Nêu hệ quả thường không mong muốn.","example":"지하철이 고장 나는 바람에 다른 노선으로 갈아탔어요. → Vì tàu điện bị hỏng nên tôi đã chuyển sang tuyến khác.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["교통","giao thông"],["지연","chậm trễ"],["사고","tai nạn"],["버스","xe buýt"],["지하철","tàu điện ngầm"],["정류장","trạm xe"],["약속 시간","giờ hẹn"],["막히다","tắc đường"],["갈아타다","chuyển tuyến"],["기다리다","chờ"]],"samples":[{"ko":"버스를 기다리느라고 약속 시간에 늦었어요.","vi":"Vì đợi xe buýt nên tôi đến muộn giờ hẹn."},{"ko":"지하철이 고장 나는 바람에 다른 노선으로 갈아탔어요.","vi":"Vì tàu điện bị hỏng nên tôi đã chuyển sang tuyến khác."},{"ko":"가장 빨리 갈 수 있는 방법을 알려 주시겠어요?","vi":"Xin chỉ giúp cách đi nhanh nhất được không?"},{"ko":"다음부터는 교통 상황을 미리 확인하겠습니다.","vi":"Từ lần sau tôi sẽ kiểm tra tình hình giao thông trước."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":3,"bai":7,"title":"Đổi trả và bảo hành","grammar":[{"formula":"-았/었는데","meaning":"đã ... nhưng / và","usage":"Dùng để nêu tình huống hoặc bối cảnh quá khứ.","example":"어제 이 옷을 샀는데 크기가 맞지 않아요. → Hôm qua tôi mua áo này nhưng kích cỡ không phù hợp.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-아/어도 되다","meaning":"được phép","usage":"Xin hoặc cho phép thực hiện hành động.","example":"영수증이 있으면 다른 상품으로 교환해도 되나요? → Nếu có hóa đơn tôi đổi sang sản phẩm khác được không?","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["영수증","hóa đơn"],["교환","đổi hàng"],["환불","hoàn tiền"],["보증","bảo hành"],["불량","lỗi sản phẩm"],["크기","kích cỡ"],["색상","màu sắc"],["구입하다","mua"],["고장 나다","bị hỏng"],["수리하다","sửa chữa"]],"samples":[{"ko":"어제 이 옷을 샀는데 크기가 맞지 않아요.","vi":"Hôm qua tôi mua áo này nhưng kích cỡ không phù hợp."},{"ko":"영수증이 있으면 다른 상품으로 교환해도 되나요?","vi":"Nếu có hóa đơn tôi đổi sang sản phẩm khác được không?"},{"ko":"제품이 처음부터 작동하지 않았습니다.","vi":"Sản phẩm ngay từ đầu đã không hoạt động."},{"ko":"환불 절차가 얼마나 걸리는지 알려 주세요.","vi":"Xin cho biết thủ tục hoàn tiền mất bao lâu."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":3,"bai":8,"title":"Mời bạn và từ chối khéo","grammar":[{"formula":"-(으)ㄹ까 하다","meaning":"đang tính, đang nghĩ sẽ","usage":"Diễn tả dự định chưa quyết định chắc chắn.","example":"이번 주말에 친구들과 같이 등산을 갈까 해요. → Cuối tuần này tôi định đi leo núi cùng bạn.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-기는 하지만","meaning":"đúng là ... nhưng","usage":"Công nhận một vế trước khi nêu ý đối lập.","example":"가고 싶기는 하지만 그날은 아르바이트가 있어요. → Tôi muốn đi nhưng hôm đó có lịch làm thêm.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["초대하다","mời"],["거절하다","từ chối"],["약속","cuộc hẹn"],["모임","buổi gặp"],["주말","cuối tuần"],["등산","leo núi"],["사정","hoàn cảnh"],["미안하다","xin lỗi"],["다음에","lần sau"],["괜찮다","ổn"]],"samples":[{"ko":"이번 주말에 친구들과 같이 등산을 갈까 해요.","vi":"Cuối tuần này tôi định đi leo núi cùng bạn."},{"ko":"가고 싶기는 하지만 그날은 아르바이트가 있어요.","vi":"Tôi muốn đi nhưng hôm đó có lịch làm thêm."},{"ko":"다음 주에 시간이 괜찮다면 함께 가요.","vi":"Nếu tuần sau có thời gian thì đi cùng nhau nhé."},{"ko":"초대해 줘서 고마워요. 다음에는 꼭 참석할게요.","vi":"Cảm ơn vì đã mời. Lần sau tôi nhất định tham gia."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":3,"bai":9,"title":"Kể lại trải nghiệm","grammar":[{"formula":"-(으)ㄴ 적이 있다","meaning":"đã từng","usage":"Nói về kinh nghiệm trong quá khứ.","example":"지난 겨울에 제주도에 가 본 적이 있어요. → Mùa đông trước tôi từng đến đảo Jeju.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-더라고요","meaning":"tôi nhận thấy / hóa ra","usage":"Nêu điều trực tiếp trải nghiệm hoặc phát hiện.","example":"직접 가 보니까 사진보다 훨씬 아름답더라고요. → Khi đến thực tế tôi thấy đẹp hơn ảnh rất nhiều.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["경험","kinh nghiệm"],["여행","du lịch"],["방문하다","thăm"],["제주도","đảo Jeju"],["기억하다","ghi nhớ"],["인상","ấn tượng"],["처음","lần đầu"],["느끼다","cảm nhận"],["추천하다","giới thiệu"],["특별하다","đặc biệt"]],"samples":[{"ko":"지난 겨울에 제주도에 가 본 적이 있어요.","vi":"Mùa đông trước tôi từng đến đảo Jeju."},{"ko":"직접 가 보니까 사진보다 훨씬 아름답더라고요.","vi":"Khi đến thực tế tôi thấy đẹp hơn ảnh rất nhiều."},{"ko":"날씨가 갑자기 추워져서 따뜻한 옷이 필요했어요.","vi":"Thời tiết đột nhiên lạnh nên tôi cần quần áo ấm."},{"ko":"그 경험 덕분에 여행 준비의 중요성을 알게 됐어요.","vi":"Nhờ trải nghiệm đó tôi hiểu tầm quan trọng của việc chuẩn bị du lịch."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":3,"bai":10,"title":"Lập kế hoạch học tập","grammar":[{"formula":"-(으)ㄹ 계획이다","meaning":"có kế hoạch","usage":"Nói kế hoạch trong tương lai.","example":"다음 달까지 한국어 단어를 오백 개 외울 계획이에요. → Tôi định học thuộc 500 từ tiếng Hàn trước tháng sau.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-도록 하다","meaning":"cố gắng / bảo đảm làm","usage":"Diễn tả sự sắp xếp hoặc yêu cầu thực hiện.","example":"매일 조금씩 복습하도록 하겠습니다. → Tôi sẽ cố gắng ôn tập một chút mỗi ngày.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["계획","kế hoạch"],["목표","mục tiêu"],["학습","học tập"],["복습하다","ôn lại"],["예습하다","chuẩn bị bài"],["단어","từ vựng"],["외우다","học thuộc"],["실력","năng lực"],["연습하다","luyện tập"],["꾸준히","đều đặn"]],"samples":[{"ko":"다음 달까지 한국어 단어를 오백 개 외울 계획이에요.","vi":"Tôi định học thuộc 500 từ tiếng Hàn trước tháng sau."},{"ko":"매일 조금씩 복습하도록 하겠습니다.","vi":"Tôi sẽ cố gắng ôn tập một chút mỗi ngày."},{"ko":"어려운 문법은 예문을 만들어 보면서 연습해요.","vi":"Tôi luyện ngữ pháp khó bằng cách thử đặt câu ví dụ."},{"ko":"계획을 지키지 못하면 이유를 기록하고 다시 시작해요.","vi":"Nếu không giữ được kế hoạch tôi ghi lại lý do rồi bắt đầu lại."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":3,"bai":11,"title":"So sánh lựa chọn","grammar":[{"formula":"-보다","meaning":"hơn / so với","usage":"So sánh hai đối tượng.","example":"버스보다 지하철이 빠른 편이에요. → Tàu điện thường nhanh hơn xe buýt.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-(으)ㄴ/는 편이다","meaning":"thuộc dạng, tương đối","usage":"Diễn tả xu hướng hoặc mức độ tương đối.","example":"이 식당은 가격이 저렴한 대신 사람이 많아요. → Quán này giá rẻ nhưng bù lại đông người.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["비교하다","so sánh"],["선택","lựa chọn"],["지하철","tàu điện"],["버스","xe buýt"],["빠르다","nhanh"],["편리하다","tiện lợi"],["가격","giá cả"],["장점","ưu điểm"],["단점","nhược điểm"],["이용하다","sử dụng"]],"samples":[{"ko":"버스보다 지하철이 빠른 편이에요.","vi":"Tàu điện thường nhanh hơn xe buýt."},{"ko":"이 식당은 가격이 저렴한 대신 사람이 많아요.","vi":"Quán này giá rẻ nhưng bù lại đông người."},{"ko":"저는 조용한 곳에서 공부하는 편입니다.","vi":"Tôi thường học ở nơi yên tĩnh."},{"ko":"두 가지 방법을 비교해 보고 선택하겠습니다.","vi":"Tôi sẽ so sánh hai cách rồi lựa chọn."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":3,"bai":12,"title":"Giải thích sự thay đổi","grammar":[{"formula":"-게 되다","meaning":"trở nên / được dẫn tới","usage":"Nói sự thay đổi hoàn cảnh dẫn đến kết quả.","example":"한국에 온 뒤로 아침에 일찍 일어나게 됐어요. → Sau khi đến Hàn tôi đã quen dậy sớm.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-아/어지다","meaning":"trở nên","usage":"Nói sự thay đổi trạng thái hoặc tính chất.","example":"한국어로 대화하는 일이 점점 자연스러워졌어요. → Việc nói chuyện bằng tiếng Hàn ngày càng tự nhiên.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["변화","thay đổi"],["습관","thói quen"],["적응하다","thích nghi"],["달라지다","trở nên khác"],["익숙하다","quen thuộc"],["생활","cuộc sống"],["규칙적이다","đều đặn"],["늘다","tăng lên"],["줄다","giảm đi"],["노력하다","cố gắng"]],"samples":[{"ko":"한국에 온 뒤로 아침에 일찍 일어나게 됐어요.","vi":"Sau khi đến Hàn tôi đã quen dậy sớm."},{"ko":"한국어로 대화하는 일이 점점 자연스러워졌어요.","vi":"Việc nói chuyện bằng tiếng Hàn ngày càng tự nhiên."},{"ko":"처음에는 어려웠지만 이제는 혼자 은행에 갈 수 있어요.","vi":"Lúc đầu khó nhưng nay tôi có thể tự đi ngân hàng."},{"ko":"새로운 환경 덕분에 자신감이 많이 생겼습니다.","vi":"Nhờ môi trường mới tôi tự tin hơn nhiều."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":3,"bai":13,"title":"Góp ý tại nơi làm việc","grammar":[{"formula":"-(으)면 좋겠다","meaning":"giá mà, mong rằng","usage":"Bày tỏ mong muốn.","example":"주문이 많을 때는 직원이 한 명 더 있으면 좋겠어요. → Khi nhiều đơn hàng thì tốt hơn nếu có thêm một nhân viên.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-는 게 어때요","meaning":"thử ... xem sao","usage":"Đưa ra lời đề nghị hoặc gợi ý.","example":"업무 순서를 먼저 정리하는 게 어때요? → Hay là chúng ta sắp xếp thứ tự công việc trước?","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["제안하다","đề xuất"],["의견","ý kiến"],["직원","nhân viên"],["업무","công việc"],["주문","đơn hàng"],["바쁘다","bận"],["개선하다","cải thiện"],["부족하다","thiếu"],["도와주다","giúp"],["협력하다","hợp tác"]],"samples":[{"ko":"주문이 많을 때는 직원이 한 명 더 있으면 좋겠어요.","vi":"Khi nhiều đơn hàng thì tốt hơn nếu có thêm một nhân viên."},{"ko":"업무 순서를 먼저 정리하는 게 어때요?","vi":"Hay là chúng ta sắp xếp thứ tự công việc trước?"},{"ko":"고객이 기다리지 않도록 미리 준비해야 합니다.","vi":"Chúng ta nên chuẩn bị sẵn để khách không phải đợi."},{"ko":"제 의견을 들어 주셔서 감사합니다.","vi":"Cảm ơn anh/chị đã lắng nghe ý kiến của tôi."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":3,"bai":14,"title":"Tin tức và thông báo","grammar":[{"formula":"-다고 하다","meaning":"nghe nói / nói rằng","usage":"Tường thuật lại lời nói.","example":"학교 공지에 따르면 다음 주 수업 시간이 바뀐다고 해요. → Theo thông báo trường, giờ học sẽ thay đổi tuần sau.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-에 따르면","meaning":"theo","usage":"Dẫn nguồn thông tin.","example":"친구가 오늘부터 도서관 이용 시간이 늘어난다고 했어요. → Bạn tôi nói từ hôm nay giờ mở cửa thư viện tăng lên.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["뉴스","tin tức"],["공지","thông báo"],["일정","lịch trình"],["변경","thay đổi"],["소식","tin mới"],["발표하다","thông báo"],["확인하다","kiểm tra"],["전하다","truyền đạt"],["수업","giờ học"],["안내하다","hướng dẫn"]],"samples":[{"ko":"학교 공지에 따르면 다음 주 수업 시간이 바뀐다고 해요.","vi":"Theo thông báo trường, giờ học sẽ thay đổi tuần sau."},{"ko":"친구가 오늘부터 도서관 이용 시간이 늘어난다고 했어요.","vi":"Bạn tôi nói từ hôm nay giờ mở cửa thư viện tăng lên."},{"ko":"정확한 내용은 공식 홈페이지에서 확인했어요.","vi":"Tôi đã kiểm tra nội dung chính xác trên trang chính thức."},{"ko":"확인되지 않은 소문은 다른 사람에게 전달하지 않아요.","vi":"Tôi không truyền đi tin đồn chưa được xác minh."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":3,"bai":15,"title":"Thuyết trình kế hoạch cá nhân","grammar":[{"formula":"-기 위해서","meaning":"để","usage":"Chỉ mục đích của hành động.","example":"한국어 실력을 높이기 위해서 매일 말하기를 연습하고 있습니다. → Để nâng cao tiếng Hàn tôi luyện nói mỗi ngày.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-(으)ㄹ 예정이다","meaning":"dự kiến sẽ","usage":"Nói kế hoạch hay dự định tương lai.","example":"우선 기본 표현을 복습한 뒤에 토론 연습을 할 예정입니다. → Trước hết tôi sẽ ôn biểu đạt cơ bản rồi tập thảo luận.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["발표","thuyết trình"],["계획","kế hoạch"],["목표","mục tiêu"],["장래","tương lai"],["진로","định hướng nghề"],["준비하다","chuẩn bị"],["달성하다","đạt được"],["능력","năng lực"],["실천하다","thực hiện"],["예정이다","dự định"]],"samples":[{"ko":"한국어 실력을 높이기 위해서 매일 말하기를 연습하고 있습니다.","vi":"Để nâng cao tiếng Hàn tôi luyện nói mỗi ngày."},{"ko":"우선 기본 표현을 복습한 뒤에 토론 연습을 할 예정입니다.","vi":"Trước hết tôi sẽ ôn biểu đạt cơ bản rồi tập thảo luận."},{"ko":"한 달 후에는 스스로 발전한 점을 평가해 보겠습니다.","vi":"Một tháng sau tôi sẽ tự đánh giá những tiến bộ."},{"ko":"작은 목표를 꾸준히 실천하는 것이 가장 중요하다고 생각합니다.","vi":"Tôi cho rằng kiên trì thực hiện mục tiêu nhỏ là quan trọng nhất."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":4,"bai":1,"title":"Giải quyết yêu cầu khách","grammar":[{"formula":"-(으)ㄹ 경우","meaning":"trong trường hợp","usage":"Đặt điều kiện hoặc tình huống.","example":"주문이 잘못 들어간 경우에는 먼저 고객에게 사과해야 합니다. → Nếu đơn bị nhập sai, trước tiên phải xin lỗi khách.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-도록","meaning":"để / sao cho","usage":"Chỉ mục đích hoặc hướng tới kết quả.","example":"같은 문제가 반복되지 않도록 주문 내용을 다시 확인하겠습니다. → Tôi sẽ xác nhận lại đơn để lỗi không lặp lại.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["고객","khách hàng"],["요청","yêu cầu"],["주문","đơn hàng"],["사과하다","xin lỗi"],["불만","khiếu nại"],["해결책","giải pháp"],["확인하다","xác nhận"],["반복되다","lặp lại"],["발생하다","phát sinh"],["담당자","người phụ trách"]],"samples":[{"ko":"주문이 잘못 들어간 경우에는 먼저 고객에게 사과해야 합니다.","vi":"Nếu đơn bị nhập sai, trước tiên phải xin lỗi khách."},{"ko":"같은 문제가 반복되지 않도록 주문 내용을 다시 확인하겠습니다.","vi":"Tôi sẽ xác nhận lại đơn để lỗi không lặp lại."},{"ko":"고객의 요청을 충분히 듣고 가능한 해결책을 제시하겠습니다.","vi":"Tôi sẽ lắng nghe kỹ yêu cầu và đề xuất giải pháp có thể."},{"ko":"추가 비용이 발생한다면 결제 전에 안내드리겠습니다.","vi":"Nếu có chi phí bổ sung tôi sẽ báo trước khi thanh toán."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":4,"bai":2,"title":"Họp nhóm và phân công","grammar":[{"formula":"-기로 하다","meaning":"quyết định làm","usage":"Nói quyết định đã được đưa ra.","example":"이번 프로젝트에서는 제가 자료 조사를 맡기로 했습니다. → Trong dự án này tôi nhận phụ trách nghiên cứu tài liệu.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-는 데에","meaning":"trong việc","usage":"Danh từ hóa hành động để nói về mục đích hoặc sự liên quan.","example":"결과를 정리하는 데에 예상보다 많은 시간이 필요합니다. → Việc tổng hợp kết quả cần nhiều thời gian hơn dự kiến.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["회의","cuộc họp"],["팀","nhóm"],["분담하다","phân công"],["역할","vai trò"],["프로젝트","dự án"],["자료","tài liệu"],["조사","khảo sát"],["초안","bản nháp"],["공유하다","chia sẻ"],["정리하다","tổng hợp"]],"samples":[{"ko":"이번 프로젝트에서는 제가 자료 조사를 맡기로 했습니다.","vi":"Trong dự án này tôi nhận phụ trách nghiên cứu tài liệu."},{"ko":"결과를 정리하는 데에 예상보다 많은 시간이 필요합니다.","vi":"Việc tổng hợp kết quả cần nhiều thời gian hơn dự kiến."},{"ko":"서로의 역할을 명확히 하면 업무가 더 효율적입니다.","vi":"Nếu phân vai rõ ràng công việc sẽ hiệu quả hơn."},{"ko":"다음 회의 전까지 초안을 공유하겠습니다.","vi":"Tôi sẽ chia sẻ bản nháp trước cuộc họp tới."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":4,"bai":3,"title":"Thuyết phục bằng lý do","grammar":[{"formula":"-기 마련이다","meaning":"thường là, tất yếu","usage":"Diễn tả kết quả được xem là thông thường.","example":"새로운 제도를 도입하면 처음에는 혼란이 생기기 마련입니다. → Khi áp dụng chế độ mới ban đầu thường có xáo trộn.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-(으)므로","meaning":"vì, do","usage":"Dẫn nguyên nhân theo văn phong trang trọng.","example":"장기적인 효과가 더 크므로 시범 운영을 제안합니다. → Vì lợi ích dài hạn lớn hơn nên tôi đề xuất thí điểm.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["설득하다","thuyết phục"],["이유","lý do"],["근거","căn cứ"],["효과","hiệu quả"],["제도","chế độ"],["도입하다","áp dụng"],["혼란","xáo trộn"],["장기적","dài hạn"],["만족도","mức hài lòng"],["제안하다","đề xuất"]],"samples":[{"ko":"새로운 제도를 도입하면 처음에는 혼란이 생기기 마련입니다.","vi":"Khi áp dụng chế độ mới ban đầu thường có xáo trộn."},{"ko":"장기적인 효과가 더 크므로 시범 운영을 제안합니다.","vi":"Vì lợi ích dài hạn lớn hơn nên tôi đề xuất thí điểm."},{"ko":"비용뿐 아니라 직원의 만족도도 고려해야 합니다.","vi":"Cần cân nhắc cả mức hài lòng nhân viên chứ không chỉ chi phí."},{"ko":"실제 사례를 바탕으로 제 의견을 설명하겠습니다.","vi":"Tôi sẽ giải thích quan điểm dựa trên ví dụ thực tế."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":4,"bai":4,"title":"Nhận xét dịch vụ","grammar":[{"formula":"-에 비해","meaning":"so với","usage":"So sánh theo tiêu chí cụ thể.","example":"이 서비스는 가격에 비해 품질이 좋은 편입니다. → Dịch vụ này có chất lượng khá tốt so với giá.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-는 반면","meaning":"trái lại / trong khi","usage":"Nêu hai đặc điểm đối lập.","example":"예약 과정은 편리한 반면 고객 상담은 다소 느립니다. → Quy trình đặt lịch thuận tiện nhưng tư vấn khách hơi chậm.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["평가하다","đánh giá"],["서비스","dịch vụ"],["품질","chất lượng"],["가격","giá"],["비교하다","so sánh"],["장점","ưu điểm"],["단점","nhược điểm"],["응대하다","tiếp khách"],["친절하다","thân thiện"],["기대하다","kỳ vọng"]],"samples":[{"ko":"이 서비스는 가격에 비해 품질이 좋은 편입니다.","vi":"Dịch vụ này có chất lượng khá tốt so với giá."},{"ko":"예약 과정은 편리한 반면 고객 상담은 다소 느립니다.","vi":"Quy trình đặt lịch thuận tiện nhưng tư vấn khách hơi chậm."},{"ko":"이용자의 의견을 정기적으로 조사할 필요가 있습니다.","vi":"Cần khảo sát ý kiến người dùng định kỳ."},{"ko":"개선할 부분을 구체적으로 정리해 전달하겠습니다.","vi":"Tôi sẽ tổng hợp cụ thể điểm cần cải thiện để gửi."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":4,"bai":5,"title":"Giải quyết bất đồng","grammar":[{"formula":"-더라도","meaning":"dù có ... thì","usage":"Nêu nhượng bộ hoặc giả định trái ý.","example":"서로 생각이 다르더라도 끝까지 존중해야 합니다. → Dù suy nghĩ khác nhau cũng phải tôn trọng nhau đến cùng.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-는 대신","meaning":"thay vì / đổi lại","usage":"Nêu lựa chọn thay thế hoặc đánh đổi.","example":"바로 결론을 내리는 대신 서로의 이유부터 들어 봅시다. → Thay vì kết luận ngay, hãy nghe lý do hai bên trước.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["의견","quan điểm"],["갈등","bất đồng"],["존중하다","tôn trọng"],["조정하다","điều chỉnh"],["양보하다","nhượng bộ"],["합의하다","thống nhất"],["상대방","đối phương"],["대안","phương án khác"],["협의하다","thảo luận"],["이해하다","thấu hiểu"]],"samples":[{"ko":"서로 생각이 다르더라도 끝까지 존중해야 합니다.","vi":"Dù suy nghĩ khác nhau cũng phải tôn trọng nhau đến cùng."},{"ko":"바로 결론을 내리는 대신 서로의 이유부터 들어 봅시다.","vi":"Thay vì kết luận ngay, hãy nghe lý do hai bên trước."},{"ko":"공통된 목표를 확인하면 타협점을 찾기가 쉬워집니다.","vi":"Nếu xác nhận mục tiêu chung sẽ dễ tìm điểm thỏa hiệp."},{"ko":"상대방의 말을 끝까지 듣고 차분하게 답하겠습니다.","vi":"Tôi sẽ nghe hết lời đối phương và trả lời bình tĩnh."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":4,"bai":6,"title":"Văn hóa công sở","grammar":[{"formula":"-에 따라","meaning":"tùy theo / theo","usage":"Chỉ sự phụ thuộc hoặc căn cứ.","example":"회사에 따라 회의 문화와 의사소통 방식이 다를 수 있습니다. → Tùy công ty, văn hóa họp và giao tiếp có thể khác.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-는 편이다","meaning":"có xu hướng","usage":"Nói khuynh hướng tương đối.","example":"한국에서는 직급에 따라 사용하는 표현이 달라지는 편입니다. → Ở Hàn cách nói thường thay đổi theo chức vụ.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["직장","nơi làm việc"],["문화","văn hóa"],["소통","giao tiếp"],["상사","cấp trên"],["동료","đồng nghiệp"],["회의","cuộc họp"],["보고하다","báo cáo"],["관계","mối quan hệ"],["예절","phép lịch sự"],["협력","hợp tác"]],"samples":[{"ko":"회사에 따라 회의 문화와 의사소통 방식이 다를 수 있습니다.","vi":"Tùy công ty, văn hóa họp và giao tiếp có thể khác."},{"ko":"한국에서는 직급에 따라 사용하는 표현이 달라지는 편입니다.","vi":"Ở Hàn cách nói thường thay đổi theo chức vụ."},{"ko":"상대방에게 불편함을 주지 않도록 예의를 지키겠습니다.","vi":"Tôi sẽ giữ phép lịch sự để không gây khó chịu cho người khác."},{"ko":"모르는 관습이 있다면 먼저 질문하는 것이 좋습니다.","vi":"Nếu có tập quán chưa biết nên hỏi trước."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":4,"bai":7,"title":"Ứng phó sự cố công việc","grammar":[{"formula":"-는 즉시","meaning":"ngay khi","usage":"Nêu hành động ngay sau việc khác.","example":"문제가 발생하는 즉시 담당자에게 보고하겠습니다. → Ngay khi sự cố xảy ra tôi sẽ báo người phụ trách.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-아/어 놓다","meaning":"làm trước và để nguyên","usage":"Nêu kết quả hành động được giữ lại.","example":"고객에게 설명할 내용을 미리 정리해 놓았습니다. → Tôi đã chuẩn bị trước nội dung giải thích cho khách.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["문제","vấn đề"],["발생하다","phát sinh"],["담당자","người phụ trách"],["보고하다","báo cáo"],["즉시","ngay lập tức"],["대응하다","ứng phó"],["점검하다","kiểm tra"],["안전","an toàn"],["예방하다","phòng ngừa"],["절차","quy trình"]],"samples":[{"ko":"문제가 발생하는 즉시 담당자에게 보고하겠습니다.","vi":"Ngay khi sự cố xảy ra tôi sẽ báo người phụ trách."},{"ko":"고객에게 설명할 내용을 미리 정리해 놓았습니다.","vi":"Tôi đã chuẩn bị trước nội dung giải thích cho khách."},{"ko":"원인을 파악하기 전에는 추측을 사실처럼 말하지 않겠습니다.","vi":"Trước khi xác định nguyên nhân tôi không nói suy đoán như sự thật."},{"ko":"처리 결과를 문서로 남겨 다시 확인할 수 있게 하겠습니다.","vi":"Tôi sẽ lưu kết quả xử lý thành văn bản để kiểm tra lại."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":4,"bai":8,"title":"Sức khỏe tinh thần","grammar":[{"formula":"-는 동안","meaning":"trong khi, trong suốt lúc","usage":"Chỉ khoảng thời gian một việc đang diễn ra.","example":"시험을 준비하는 동안 스트레스를 적절히 관리해야 합니다. → Trong thời gian ôn thi cần quản lý căng thẳng phù hợp.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-고 나면","meaning":"sau khi làm xong","usage":"Nói thời điểm sau khi hoàn thành.","example":"잠깐 산책하고 나면 집중력이 좋아지는 것 같습니다. → Sau khi đi dạo một chút tôi thấy tập trung tốt hơn.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["스트레스","căng thẳng"],["건강","sức khỏe"],["감정","cảm xúc"],["휴식","nghỉ ngơi"],["관리하다","quản lý"],["상담","tư vấn"],["수면","giấc ngủ"],["불안","lo âu"],["피로","mệt mỏi"],["회복하다","phục hồi"]],"samples":[{"ko":"시험을 준비하는 동안 스트레스를 적절히 관리해야 합니다.","vi":"Trong thời gian ôn thi cần quản lý căng thẳng phù hợp."},{"ko":"잠깐 산책하고 나면 집중력이 좋아지는 것 같습니다.","vi":"Sau khi đi dạo một chút tôi thấy tập trung tốt hơn."},{"ko":"무리한 계획보다 실천 가능한 습관이 오래 유지됩니다.","vi":"Thói quen khả thi duy trì lâu hơn kế hoạch quá sức."},{"ko":"힘들 때는 혼자 참지 말고 주변에 도움을 요청하세요.","vi":"Khi khó khăn hãy nhờ hỗ trợ thay vì chịu một mình."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":4,"bai":9,"title":"Bảo vệ môi trường","grammar":[{"formula":"-(으)ㄹ수록","meaning":"càng ... càng","usage":"Diễn tả sự thay đổi tỷ lệ thuận.","example":"일회용품을 줄일수록 쓰레기 배출량도 감소합니다. → Càng giảm đồ dùng một lần lượng rác càng giảm.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-아/어야 한다","meaning":"phải","usage":"Diễn tả nghĩa vụ.","example":"환경 보호는 개인뿐 아니라 기업도 함께 참여해야 합니다. → Không chỉ cá nhân mà doanh nghiệp cũng cần tham gia bảo vệ môi trường.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["환경","môi trường"],["쓰레기","rác thải"],["재활용","tái chế"],["일회용품","đồ dùng một lần"],["줄이다","giảm"],["보호하다","bảo vệ"],["배출하다","thải ra"],["에너지","năng lượng"],["실천하다","thực hiện"],["절약하다","tiết kiệm"]],"samples":[{"ko":"일회용품을 줄일수록 쓰레기 배출량도 감소합니다.","vi":"Càng giảm đồ dùng một lần lượng rác càng giảm."},{"ko":"환경 보호는 개인뿐 아니라 기업도 함께 참여해야 합니다.","vi":"Không chỉ cá nhân mà doanh nghiệp cũng cần tham gia bảo vệ môi trường."},{"ko":"작은 실천이 모이면 사회적인 변화를 만들 수 있습니다.","vi":"Hành động nhỏ tích lũy có thể tạo ra thay đổi xã hội."},{"ko":"분리배출 방법을 모를 때는 지침을 확인하는 습관이 필요합니다.","vi":"Khi chưa biết cách phân loại rác cần thói quen xem hướng dẫn."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":4,"bai":10,"title":"Ứng xử trên mạng","grammar":[{"formula":"-는 듯하다","meaning":"dường như","usage":"Nêu suy đoán hoặc cảm nhận.","example":"짧은 메시지는 감정을 정확하게 전달하지 못하는 듯합니다. → Tin nhắn ngắn dường như không truyền tải chính xác cảm xúc.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-아/어서는 안 되다","meaning":"không được phép","usage":"Nêu sự cấm đoán mạnh.","example":"확인되지 않은 개인정보를 온라인에 올려서는 안 됩니다. → Không được đăng thông tin cá nhân chưa được xác nhận lên mạng.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["온라인","trực tuyến"],["댓글","bình luận"],["정보","thông tin"],["오해","hiểu lầm"],["감정","cảm xúc"],["예절","quy tắc ứng xử"],["공유하다","chia sẻ"],["조심하다","cẩn thận"],["표현하다","biểu đạt"],["책임","trách nhiệm"]],"samples":[{"ko":"짧은 메시지는 감정을 정확하게 전달하지 못하는 듯합니다.","vi":"Tin nhắn ngắn dường như không truyền tải chính xác cảm xúc."},{"ko":"확인되지 않은 개인정보를 온라인에 올려서는 안 됩니다.","vi":"Không được đăng thông tin cá nhân chưa được xác nhận lên mạng."},{"ko":"오해가 생기면 공개적으로 다투기보다 직접 설명하는 편이 좋습니다.","vi":"Khi hiểu lầm, giải thích trực tiếp tốt hơn cãi nhau công khai."},{"ko":"상대방의 입장을 고려해 표현을 선택하겠습니다.","vi":"Tôi sẽ cân nhắc góc nhìn đối phương khi chọn cách diễn đạt."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":4,"bai":11,"title":"Học qua dự án","grammar":[{"formula":"-(으)면서","meaning":"trong khi / đồng thời","usage":"Hai hành động cùng xảy ra.","example":"자료를 수집하면서 예상하지 못한 문제를 발견했습니다. → Khi thu thập dữ liệu tôi đã phát hiện vấn đề không ngờ.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-도록 하다","meaning":"cố gắng / bảo đảm làm","usage":"Diễn tả sự sắp xếp hoặc yêu cầu thực hiện.","example":"조원들이 의견을 자유롭게 제시하도록 분위기를 만들었습니다. → Chúng tôi tạo không khí để thành viên nêu ý kiến tự do.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["과제","bài tập/dự án"],["팀원","thành viên nhóm"],["자료","tài liệu"],["수집하다","thu thập"],["발견하다","phát hiện"],["협업","hợp tác"],["성과","kết quả"],["계획하다","lập kế hoạch"],["진행하다","tiến hành"],["완성하다","hoàn thành"]],"samples":[{"ko":"자료를 수집하면서 예상하지 못한 문제를 발견했습니다.","vi":"Khi thu thập dữ liệu tôi đã phát hiện vấn đề không ngờ."},{"ko":"조원들이 의견을 자유롭게 제시하도록 분위기를 만들었습니다.","vi":"Chúng tôi tạo không khí để thành viên nêu ý kiến tự do."},{"ko":"진행 상황을 정기적으로 점검하면 지연을 줄일 수 있습니다.","vi":"Kiểm tra tiến độ định kỳ giúp giảm chậm trễ."},{"ko":"이번 경험을 다음 프로젝트의 개선에 활용하겠습니다.","vi":"Tôi sẽ vận dụng kinh nghiệm lần này vào dự án tiếp theo."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":4,"bai":12,"title":"Xu hướng tiêu dùng","grammar":[{"formula":"-에 따르면","meaning":"theo","usage":"Dẫn nguồn thông tin.","example":"최근 조사에 따르면 온라인 구매가 증가하는 경향이 있습니다. → Theo khảo sát gần đây, mua sắm online có xu hướng tăng.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-는 경향이 있다","meaning":"có xu hướng","usage":"Nói khuynh hướng thường gặp.","example":"소비자들은 가격뿐 아니라 배송 속도도 중요하게 생각합니다. → Người tiêu dùng coi trọng không chỉ giá mà cả tốc độ giao hàng.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["소비","tiêu dùng"],["경향","xu hướng"],["구매","mua sắm"],["온라인","trực tuyến"],["조사","khảo sát"],["통계","thống kê"],["증가하다","tăng lên"],["감소하다","giảm xuống"],["고객","khách hàng"],["선호하다","ưa chuộng"]],"samples":[{"ko":"최근 조사에 따르면 온라인 구매가 증가하는 경향이 있습니다.","vi":"Theo khảo sát gần đây, mua sắm online có xu hướng tăng."},{"ko":"소비자들은 가격뿐 아니라 배송 속도도 중요하게 생각합니다.","vi":"Người tiêu dùng coi trọng không chỉ giá mà cả tốc độ giao hàng."},{"ko":"다만 모든 연령층에서 같은 결과가 나타나지는 않습니다.","vi":"Tuy nhiên không phải nhóm tuổi nào cũng có kết quả giống nhau."},{"ko":"자료를 비교할 때는 조사 방법과 표본도 확인해야 합니다.","vi":"Khi so sánh dữ liệu cần xem cả phương pháp và mẫu khảo sát."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":4,"bai":13,"title":"Giải thích quy trình","grammar":[{"formula":"-에 앞서","meaning":"trước khi","usage":"Nói việc diễn ra trước sự kiện khác.","example":"신청서를 제출하기에 앞서 필요한 서류를 확인하세요. → Trước khi nộp đơn hãy kiểm tra giấy tờ cần thiết.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-고 나서","meaning":"sau khi","usage":"Nói thứ tự hành động.","example":"모든 정보를 입력하고 나서 내용을 다시 검토합니다. → Sau khi nhập tất cả thông tin hãy rà soát lại.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["절차","quy trình"],["신청서","đơn đăng ký"],["제출하다","nộp"],["서류","giấy tờ"],["단계","bước"],["확인하다","xác nhận"],["순서","thứ tự"],["작성하다","soạn"],["처리하다","xử lý"],["안내하다","hướng dẫn"]],"samples":[{"ko":"신청서를 제출하기에 앞서 필요한 서류를 확인하세요.","vi":"Trước khi nộp đơn hãy kiểm tra giấy tờ cần thiết."},{"ko":"모든 정보를 입력하고 나서 내용을 다시 검토합니다.","vi":"Sau khi nhập tất cả thông tin hãy rà soát lại."},{"ko":"승인이 완료되면 담당자에게 결과를 알려 주세요.","vi":"Khi phê duyệt hoàn tất hãy thông báo cho người phụ trách."},{"ko":"과정 중에 문제가 생기면 즉시 지원 센터에 문의하세요.","vi":"Nếu có vấn đề trong quá trình hãy hỏi trung tâm hỗ trợ ngay."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":4,"bai":14,"title":"Tóm tắt và báo cáo","grammar":[{"formula":"-을/를 중심으로","meaning":"lấy ... làm trọng tâm","usage":"Xác định nội dung trung tâm.","example":"이번 발표는 조사 결과를 중심으로 정리했습니다. → Bài trình bày này tập trung tổng hợp kết quả khảo sát.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-다고 볼 수 있다","meaning":"có thể coi là","usage":"Nêu cách nhìn hoặc kết luận thận trọng.","example":"응답자의 절반 이상이 변화에 긍정적이었다고 볼 수 있습니다. → Có thể thấy hơn một nửa người trả lời đánh giá tích cực về thay đổi.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["보고서","báo cáo"],["요약하다","tóm tắt"],["분석하다","phân tích"],["결과","kết quả"],["조사","khảo sát"],["자료","dữ liệu"],["핵심","trọng tâm"],["평가하다","đánh giá"],["근거","căn cứ"],["정리하다","tổng hợp"]],"samples":[{"ko":"이번 발표는 조사 결과를 중심으로 정리했습니다.","vi":"Bài trình bày này tập trung tổng hợp kết quả khảo sát."},{"ko":"응답자의 절반 이상이 변화에 긍정적이었다고 볼 수 있습니다.","vi":"Có thể thấy hơn một nửa người trả lời đánh giá tích cực về thay đổi."},{"ko":"하지만 몇 가지 한계가 있으므로 해석에 주의해야 합니다.","vi":"Tuy nhiên có vài hạn chế nên cần thận trọng khi diễn giải."},{"ko":"마지막으로 개선 방향을 세 가지로 나누어 제안하겠습니다.","vi":"Cuối cùng tôi đề xuất hướng cải tiến theo ba phần."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":4,"bai":15,"title":"Thuyết trình tổng hợp","grammar":[{"formula":"-는 반면","meaning":"trái lại / trong khi","usage":"Nêu hai đặc điểm đối lập.","example":"저는 오늘 청년의 시간 관리에 대해 말씀드리겠습니다. → Hôm nay tôi xin trình bày về quản lý thời gian của người trẻ.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-기 위해","meaning":"để","usage":"Nêu mục đích.","example":"기술은 효율을 높이는 반면 새로운 부담을 만들기도 합니다. → Công nghệ tăng hiệu suất nhưng cũng tạo gánh nặng mới.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["발표","thuyết trình"],["관리하다","quản lý"],["시간","thời gian"],["청중","người nghe"],["핵심","trọng tâm"],["자료","tài liệu"],["근거","căn cứ"],["결론","kết luận"],["질문","câu hỏi"],["설명하다","giải thích"]],"samples":[{"ko":"저는 오늘 청년의 시간 관리에 대해 말씀드리겠습니다.","vi":"Hôm nay tôi xin trình bày về quản lý thời gian của người trẻ."},{"ko":"기술은 효율을 높이는 반면 새로운 부담을 만들기도 합니다.","vi":"Công nghệ tăng hiệu suất nhưng cũng tạo gánh nặng mới."},{"ko":"균형을 유지하기 위해 개인과 조직의 노력이 모두 필요합니다.","vi":"Để giữ cân bằng cần nỗ lực cả cá nhân lẫn tổ chức."},{"ko":"이러한 이유로 실천 가능한 계획부터 시작할 것을 제안합니다.","vi":"Vì vậy tôi đề xuất bắt đầu từ kế hoạch có thể thực hiện."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":5,"bai":1,"title":"Tranh luận giáo dục số","grammar":[{"formula":"-다는 점에서","meaning":"ở điểm rằng","usage":"Đánh giá dựa trên một khía cạnh.","example":"온라인 교육은 접근성을 높인다는 점에서 긍정적으로 평가할 수 있습니다. → Giáo dục trực tuyến tích cực ở khía cạnh tăng khả năng tiếp cận.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-지 않을 수 없다","meaning":"không thể không","usage":"Nói điều khó tránh hoặc buộc phải thừa nhận.","example":"그러나 학습 격차가 확대될 가능성을 무시할 수는 없습니다. → Tuy nhiên không thể bỏ qua khả năng khoảng cách học tập tăng lên.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["교육","giáo dục"],["온라인","trực tuyến"],["접근성","khả năng tiếp cận"],["격차","khoảng cách"],["효율성","hiệu quả"],["형평성","công bằng"],["학습","học tập"],["정책","chính sách"],["도입하다","áp dụng"],["평가하다","đánh giá"]],"samples":[{"ko":"온라인 교육은 접근성을 높인다는 점에서 긍정적으로 평가할 수 있습니다.","vi":"Giáo dục trực tuyến tích cực ở khía cạnh tăng khả năng tiếp cận."},{"ko":"그러나 학습 격차가 확대될 가능성을 무시할 수는 없습니다.","vi":"Tuy nhiên không thể bỏ qua khả năng khoảng cách học tập tăng lên."},{"ko":"기술 도입의 효과를 판단하려면 장기적인 자료가 필요합니다.","vi":"Muốn đánh giá hiệu quả áp dụng công nghệ cần dữ liệu dài hạn."},{"ko":"따라서 효율성과 형평성을 함께 고려한 정책이 바람직합니다.","vi":"Vì vậy chính sách cân nhắc cả hiệu quả và công bằng là phù hợp."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":5,"bai":2,"title":"Xác minh thông tin","grammar":[{"formula":"-에 불과하다","meaning":"chỉ là","usage":"Giới hạn mức độ hoặc ý nghĩa.","example":"조회 수가 많다는 사실만으로 정보의 정확성을 보장할 수는 없습니다. → Nhiều lượt xem không đảm bảo tính chính xác của thông tin.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-다는 사실","meaning":"sự thật rằng","usage":"Danh từ hóa mệnh đề để nêu sự thật.","example":"일부 사례는 전체 현상을 보여 주는 자료에 불과할 수 있습니다. → Một số ví dụ có thể chỉ là tư liệu không phản ánh toàn bộ hiện tượng.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["정보","thông tin"],["출처","nguồn"],["정확성","tính chính xác"],["검증하다","kiểm chứng"],["근거","căn cứ"],["자료","dữ liệu"],["주장","luận điểm"],["왜곡","biến dạng"],["공유하다","chia sẻ"],["재확인하다","kiểm tra lại"]],"samples":[{"ko":"조회 수가 많다는 사실만으로 정보의 정확성을 보장할 수는 없습니다.","vi":"Nhiều lượt xem không đảm bảo tính chính xác của thông tin."},{"ko":"일부 사례는 전체 현상을 보여 주는 자료에 불과할 수 있습니다.","vi":"Một số ví dụ có thể chỉ là tư liệu không phản ánh toàn bộ hiện tượng."},{"ko":"주장의 근거와 조사 방식을 동시에 검토해야 합니다.","vi":"Cần đánh giá đồng thời bằng chứng và phương pháp khảo sát."},{"ko":"출처가 불분명한 정보는 공유하기 전에 재확인하겠습니다.","vi":"Tôi sẽ kiểm tra lại thông tin không rõ nguồn trước khi chia sẻ."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":5,"bai":3,"title":"Quyền lợi lao động","grammar":[{"formula":"-도록 보장하다","meaning":"bảo đảm để","usage":"Diễn tả việc bảo đảm điều kiện đạt được mục tiêu.","example":"근로자가 충분히 휴식할 수 있도록 제도적으로 보장해야 합니다. → Cần bảo đảm bằng thể chế để người lao động được nghỉ đầy đủ.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-는 한","meaning":"chừng nào còn / miễn là","usage":"Chỉ điều kiện duy trì.","example":"계약 내용이 명확하지 않은 한 분쟁이 반복될 수 있습니다. → Nếu hợp đồng không rõ, tranh chấp có thể lặp lại.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["노동","lao động"],["권리","quyền lợi"],["근로자","người lao động"],["계약","hợp đồng"],["휴식","nghỉ ngơi"],["보장하다","bảo đảm"],["분쟁","tranh chấp"],["사업주","chủ doanh nghiệp"],["기준","tiêu chuẩn"],["대안","phương án"]],"samples":[{"ko":"근로자가 충분히 휴식할 수 있도록 제도적으로 보장해야 합니다.","vi":"Cần bảo đảm bằng thể chế để người lao động được nghỉ đầy đủ."},{"ko":"계약 내용이 명확하지 않은 한 분쟁이 반복될 수 있습니다.","vi":"Nếu hợp đồng không rõ, tranh chấp có thể lặp lại."},{"ko":"합리적인 기준은 사업주와 근로자 모두에게 도움이 됩니다.","vi":"Tiêu chuẩn hợp lý có lợi cho cả chủ và người lao động."},{"ko":"구체적인 사례를 토대로 실현 가능한 대안을 제시하겠습니다.","vi":"Tôi sẽ đưa ra phương án khả thi dựa trên tình huống cụ thể."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":5,"bai":4,"title":"Đô thị và giao thông","grammar":[{"formula":"-에 기여하다","meaning":"đóng góp vào","usage":"Nêu tác động tích cực tới kết quả.","example":"대중교통 확대는 교통 혼잡 완화에 기여할 수 있습니다. → Mở rộng giao thông công cộng có thể góp phần giảm ùn tắc.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-에도 불구하고","meaning":"mặc dù","usage":"Diễn tả sự nhượng bộ dù có trở ngại.","example":"예산 부족에도 불구하고 단계적인 투자가 필요합니다. → Mặc dù thiếu ngân sách vẫn cần đầu tư theo giai đoạn.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["도시","đô thị"],["교통","giao thông"],["혼잡","ùn tắc"],["대중교통","giao thông công cộng"],["정책","chính sách"],["확대하다","mở rộng"],["완화하다","giảm nhẹ"],["접근성","khả năng tiếp cận"],["지속가능성","tính bền vững"],["발전","phát triển"]],"samples":[{"ko":"대중교통 확대는 교통 혼잡 완화에 기여할 수 있습니다.","vi":"Mở rộng giao thông công cộng có thể góp phần giảm ùn tắc."},{"ko":"예산 부족에도 불구하고 단계적인 투자가 필요합니다.","vi":"Mặc dù thiếu ngân sách vẫn cần đầu tư theo giai đoạn."},{"ko":"정책 효과를 평가할 때 시민의 이동권도 고려해야 합니다.","vi":"Khi đánh giá chính sách cần cân nhắc quyền đi lại của công dân."},{"ko":"장기적인 비용과 환경적 영향을 함께 비교하겠습니다.","vi":"Tôi sẽ so sánh đồng thời chi phí dài hạn và tác động môi trường."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":5,"bai":5,"title":"Bảo tồn văn hóa","grammar":[{"formula":"-의 관점에서","meaning":"từ góc nhìn","usage":"Nêu quan điểm xem xét.","example":"문화유산은 관광 자원의 관점에서만 이해해서는 안 됩니다. → Không nên hiểu di sản văn hóa chỉ ở góc độ tài nguyên du lịch.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-는 데 그치지 않다","meaning":"không chỉ dừng ở","usage":"Nhấn mạnh phạm vi vượt quá một hành động.","example":"보존은 건물을 유지하는 데 그치지 않고 공동체의 기억을 지키는 일입니다. → Bảo tồn không dừng ở giữ công trình mà còn giữ ký ức cộng đồng.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["문화유산","di sản văn hóa"],["보존하다","bảo tồn"],["전통","truyền thống"],["관광","du lịch"],["정체성","bản sắc"],["세대","thế hệ"],["역사","lịch sử"],["해석하다","diễn giải"],["계승하다","kế thừa"],["가치","giá trị"]],"samples":[{"ko":"문화유산은 관광 자원의 관점에서만 이해해서는 안 됩니다.","vi":"Không nên hiểu di sản văn hóa chỉ ở góc độ tài nguyên du lịch."},{"ko":"보존은 건물을 유지하는 데 그치지 않고 공동체의 기억을 지키는 일입니다.","vi":"Bảo tồn không dừng ở giữ công trình mà còn giữ ký ức cộng đồng."},{"ko":"지역 주민의 참여가 지속 가능한 관리의 핵심이라고 생각합니다.","vi":"Tôi cho rằng cư dân tham gia là trọng tâm của quản lý bền vững."},{"ko":"전통과 현대적 활용이 조화를 이루도록 방안을 마련해야 합니다.","vi":"Cần đề ra phương án hài hòa truyền thống và công dụng hiện đại."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":5,"bai":6,"title":"Đạo đức AI","grammar":[{"formula":"-는 반면","meaning":"trái lại / trong khi","usage":"Nêu hai đặc điểm đối lập.","example":"인공지능은 작업 효율을 높이는 반면 편향을 확대할 위험도 있습니다. → AI nâng hiệu suất nhưng cũng có nguy cơ khuếch đại thiên kiến.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-지 않도록","meaning":"để không","usage":"Diễn tả mục đích tránh sự việc.","example":"개인정보가 무단으로 활용되지 않도록 관리 체계가 필요합니다. → Cần hệ thống quản lý để dữ liệu cá nhân không bị dùng trái phép.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["인공지능","trí tuệ nhân tạo"],["윤리","đạo đức"],["편향","thiên lệch"],["효율","hiệu quả"],["위험","rủi ro"],["책임","trách nhiệm"],["판단하다","đánh giá"],["활용하다","ứng dụng"],["기술","công nghệ"],["보호하다","bảo vệ"]],"samples":[{"ko":"인공지능은 작업 효율을 높이는 반면 편향을 확대할 위험도 있습니다.","vi":"AI nâng hiệu suất nhưng cũng có nguy cơ khuếch đại thiên kiến."},{"ko":"개인정보가 무단으로 활용되지 않도록 관리 체계가 필요합니다.","vi":"Cần hệ thống quản lý để dữ liệu cá nhân không bị dùng trái phép."},{"ko":"기술의 결정 과정을 설명할 책임이 누구에게 있는지 논의해야 합니다.","vi":"Cần thảo luận ai có trách nhiệm giải thích quyết định của công nghệ."},{"ko":"혁신의 속도와 사회적 안전 사이에서 균형을 찾아야 합니다.","vi":"Phải tìm cân bằng giữa tốc độ đổi mới và an toàn xã hội."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":5,"bai":7,"title":"Biến đổi khí hậu","grammar":[{"formula":"-에 따른","meaning":"theo / do ... dẫn tới","usage":"Chỉ sự phụ thuộc hoặc hệ quả.","example":"기후 변화에 따른 위험은 지역과 계층에 따라 다르게 나타납니다. → Nguy cơ do biến đổi khí hậu khác nhau theo vùng và tầng lớp.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-을/를 비롯한","meaning":"bao gồm, đứng đầu là","usage":"Đưa ví dụ tiêu biểu trong nhóm.","example":"에너지 전환을 비롯한 다양한 정책을 동시에 추진해야 합니다. → Cần đồng thời triển khai nhiều chính sách gồm chuyển đổi năng lượng.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["기후","khí hậu"],["변화","biến đổi"],["온실가스","khí nhà kính"],["위험","rủi ro"],["지역","khu vực"],["계층","tầng lớp"],["감축하다","cắt giảm"],["재난","thiên tai"],["대응하다","ứng phó"],["환경","môi trường"]],"samples":[{"ko":"기후 변화에 따른 위험은 지역과 계층에 따라 다르게 나타납니다.","vi":"Nguy cơ do biến đổi khí hậu khác nhau theo vùng và tầng lớp."},{"ko":"에너지 전환을 비롯한 다양한 정책을 동시에 추진해야 합니다.","vi":"Cần đồng thời triển khai nhiều chính sách gồm chuyển đổi năng lượng."},{"ko":"취약한 집단의 피해를 줄이는 것이 중요한 과제입니다.","vi":"Giảm thiệt hại cho nhóm dễ tổn thương là nhiệm vụ quan trọng."},{"ko":"정책의 성과를 측정할 지표도 명확히 설정해야 합니다.","vi":"Cần xác định rõ chỉ số đo lường hiệu quả chính sách."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":5,"bai":8,"title":"Dân số già hóa","grammar":[{"formula":"-에 대비하다","meaning":"chuẩn bị ứng phó","usage":"Nói việc chuẩn bị đối phó.","example":"고령화에 대비해 의료와 돌봄 체계를 함께 개선해야 합니다. → Để ứng phó già hóa cần cải thiện y tế và chăm sóc cùng lúc.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-을/를 둘러싸고","meaning":"xoay quanh","usage":"Nêu vấn đề đang tranh luận.","example":"세대 간 부담 분담을 둘러싸고 다양한 의견이 제기되고 있습니다. → Có nhiều ý kiến về phân chia gánh nặng giữa các thế hệ.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["고령화","già hóa"],["인구","dân số"],["돌봄","chăm sóc"],["의료","y tế"],["복지","phúc lợi"],["제도","chế độ"],["개선하다","cải thiện"],["세대","thế hệ"],["대비하다","chuẩn bị ứng phó"],["지원","hỗ trợ"]],"samples":[{"ko":"고령화에 대비해 의료와 돌봄 체계를 함께 개선해야 합니다.","vi":"Để ứng phó già hóa cần cải thiện y tế và chăm sóc cùng lúc."},{"ko":"세대 간 부담 분담을 둘러싸고 다양한 의견이 제기되고 있습니다.","vi":"Có nhiều ý kiến về phân chia gánh nặng giữa các thế hệ."},{"ko":"정책을 설계할 때 당사자의 목소리를 반영하는 것이 중요합니다.","vi":"Khi thiết kế chính sách cần phản ánh tiếng nói người liên quan."},{"ko":"단기적인 지원과 장기적인 구조 개혁을 병행해야 합니다.","vi":"Cần song hành hỗ trợ ngắn hạn và cải cách cơ cấu dài hạn."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":5,"bai":9,"title":"Tiêu dùng bền vững","grammar":[{"formula":"-을/를 감안하면","meaning":"nếu cân nhắc","usage":"Tính đến các điều kiện liên quan.","example":"생산 과정의 환경 비용을 감안하면 가격만으로 상품을 비교하기 어렵습니다. → Tính cả chi phí môi trường trong sản xuất thì khó so hàng chỉ bằng giá.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-뿐만 아니라","meaning":"không chỉ ... mà còn","usage":"Nối các ý bổ sung.","example":"기업뿐만 아니라 소비자도 책임 있는 선택을 해야 합니다. → Không chỉ doanh nghiệp mà người tiêu dùng cũng phải chọn lựa có trách nhiệm.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["소비","tiêu dùng"],["지속가능하다","bền vững"],["생산","sản xuất"],["환경","môi trường"],["비용","chi phí"],["상품","sản phẩm"],["재활용","tái chế"],["선택","lựa chọn"],["책임","trách nhiệm"],["절약하다","tiết kiệm"]],"samples":[{"ko":"생산 과정의 환경 비용을 감안하면 가격만으로 상품을 비교하기 어렵습니다.","vi":"Tính cả chi phí môi trường trong sản xuất thì khó so hàng chỉ bằng giá."},{"ko":"기업뿐만 아니라 소비자도 책임 있는 선택을 해야 합니다.","vi":"Không chỉ doanh nghiệp mà người tiêu dùng cũng phải chọn lựa có trách nhiệm."},{"ko":"친환경 표시가 실제 기준을 충족하는지 검증할 필요가 있습니다.","vi":"Cần xác minh nhãn thân thiện môi trường có đạt tiêu chuẩn thật không."},{"ko":"정보 공개가 확대되면 소비자의 판단도 합리적일 수 있습니다.","vi":"Minh bạch thông tin hơn sẽ giúp quyết định tiêu dùng hợp lý hơn."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":5,"bai":10,"title":"Tranh luận với số liệu","grammar":[{"formula":"-에서 알 수 있듯이","meaning":"như có thể thấy từ","usage":"Dẫn bằng chứng từ dữ liệu.","example":"이 그래프에서 알 수 있듯이 최근 이용률이 꾸준히 높아졌습니다. → Như có thể thấy từ biểu đồ, tỷ lệ sử dụng gần đây tăng đều.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-다고 단정하다","meaning":"khẳng định chắc rằng","usage":"Nêu kết luận dứt khoát.","example":"하지만 한 가지 수치만으로 원인을 단정해서는 안 됩니다. → Tuy nhiên không được kết luận nguyên nhân chỉ từ một chỉ số.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["통계","thống kê"],["자료","dữ liệu"],["비율","tỷ lệ"],["그래프","biểu đồ"],["증가하다","tăng"],["감소하다","giảm"],["해석하다","diễn giải"],["근거","căn cứ"],["추세","xu hướng"],["단정하다","kết luận quả quyết"]],"samples":[{"ko":"이 그래프에서 알 수 있듯이 최근 이용률이 꾸준히 높아졌습니다.","vi":"Như có thể thấy từ biểu đồ, tỷ lệ sử dụng gần đây tăng đều."},{"ko":"하지만 한 가지 수치만으로 원인을 단정해서는 안 됩니다.","vi":"Tuy nhiên không được kết luận nguyên nhân chỉ từ một chỉ số."},{"ko":"대상 집단의 특성을 고려하면 다른 해석도 가능합니다.","vi":"Xét đặc điểm nhóm đối tượng có thể có cách diễn giải khác."},{"ko":"추가 자료를 확보한 뒤에 결론을 수정할 수 있습니다.","vi":"Có thể sửa kết luận sau khi có thêm dữ liệu."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":5,"bai":11,"title":"Đàm phán và nhượng bộ","grammar":[{"formula":"-을/를 전제로","meaning":"với tiền đề","usage":"Nêu cơ sở của hành động.","example":"상호 신뢰를 전제로 할 때 협상이 원활하게 진행될 수 있습니다. → Đàm phán thuận lợi khi đặt trên nền tảng tin cậy lẫn nhau.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-는 대신","meaning":"thay vì / đổi lại","usage":"Nêu lựa chọn thay thế hoặc đánh đổi.","example":"일정을 연장하는 대신 품질 기준을 유지하는 방안을 제안합니다. → Tôi đề nghị gia hạn tiến độ thay vì hạ tiêu chuẩn chất lượng.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["협상","đàm phán"],["양보하다","nhượng bộ"],["조건","điều kiện"],["합의","thỏa thuận"],["신뢰","niềm tin"],["상호","lẫn nhau"],["이익","lợi ích"],["갈등","xung đột"],["대안","phương án"],["제안하다","đề xuất"]],"samples":[{"ko":"상호 신뢰를 전제로 할 때 협상이 원활하게 진행될 수 있습니다.","vi":"Đàm phán thuận lợi khi đặt trên nền tảng tin cậy lẫn nhau."},{"ko":"일정을 연장하는 대신 품질 기준을 유지하는 방안을 제안합니다.","vi":"Tôi đề nghị gia hạn tiến độ thay vì hạ tiêu chuẩn chất lượng."},{"ko":"일방적인 요구보다 공동의 이익을 확인하는 것이 중요합니다.","vi":"Xác nhận lợi ích chung quan trọng hơn yêu cầu một chiều."},{"ko":"합의한 내용은 오해가 없도록 문서로 남기겠습니다.","vi":"Tôi sẽ ghi lại thỏa thuận để tránh hiểu lầm."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":5,"bai":12,"title":"Chính sách giáo dục","grammar":[{"formula":"-에 비추어 볼 때","meaning":"xét theo","usage":"Đánh giá dựa trên bằng chứng.","example":"학습 성과에 비추어 볼 때 제도의 장단점을 다시 검토할 필요가 있습니다. → Xét kết quả học tập cần xem lại ưu nhược của chế độ.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-라는 점에서","meaning":"ở phương diện","usage":"Nêu một khía cạnh để đánh giá.","example":"교육 기회의 균등이라는 점에서 지역 간 격차를 줄여야 합니다. → Ở góc độ bình đẳng giáo dục cần giảm chênh lệch vùng miền.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["정책","chính sách"],["교육","giáo dục"],["성과","thành quả"],["제도","chế độ"],["개편","cải tổ"],["평가","đánh giá"],["형평성","tính công bằng"],["효율성","tính hiệu quả"],["근거","căn cứ"],["검토하다","xem xét"]],"samples":[{"ko":"학습 성과에 비추어 볼 때 제도의 장단점을 다시 검토할 필요가 있습니다.","vi":"Xét kết quả học tập cần xem lại ưu nhược của chế độ."},{"ko":"교육 기회의 균등이라는 점에서 지역 간 격차를 줄여야 합니다.","vi":"Ở góc độ bình đẳng giáo dục cần giảm chênh lệch vùng miền."},{"ko":"교사의 업무 부담도 제도 평가의 중요한 기준입니다.","vi":"Gánh nặng công việc giáo viên cũng là tiêu chí quan trọng."},{"ko":"실행 가능성과 공정성을 함께 반영한 대안을 제시하겠습니다.","vi":"Tôi đề xuất giải pháp phản ánh cả tính khả thi và công bằng."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":5,"bai":13,"title":"Bài trình bày học thuật","grammar":[{"formula":"-에 관한","meaning":"liên quan đến","usage":"Nêu chủ đề.","example":"오늘은 외국인 유학생의 적응 경험에 관한 연구를 소개하겠습니다. → Hôm nay tôi giới thiệu nghiên cứu về trải nghiệm thích nghi của du học sinh.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-을/를 바탕으로","meaning":"dựa trên","usage":"Nêu căn cứ hoặc nền tảng.","example":"설문 결과를 바탕으로 주요 요인을 세 가지로 정리했습니다. → Dựa vào khảo sát tôi tổng hợp ba yếu tố chính.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["연구","nghiên cứu"],["유학생","du học sinh"],["적응","thích nghi"],["경험","kinh nghiệm"],["조사","khảo sát"],["방법","phương pháp"],["분석","phân tích"],["결과","kết quả"],["발표","thuyết trình"],["자료","dữ liệu"]],"samples":[{"ko":"오늘은 외국인 유학생의 적응 경험에 관한 연구를 소개하겠습니다.","vi":"Hôm nay tôi giới thiệu nghiên cứu về trải nghiệm thích nghi của du học sinh."},{"ko":"설문 결과를 바탕으로 주요 요인을 세 가지로 정리했습니다.","vi":"Dựa vào khảo sát tôi tổng hợp ba yếu tố chính."},{"ko":"연구 대상이 제한적이라는 점은 한계로 남아 있습니다.","vi":"Giới hạn đối tượng nghiên cứu vẫn là một hạn chế."},{"ko":"끝으로 후속 연구의 방향을 제안하겠습니다.","vi":"Cuối cùng tôi đề xuất hướng nghiên cứu tiếp theo."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":5,"bai":14,"title":"Phản biện lập luận","grammar":[{"formula":"-다고 보기 어렵다","meaning":"khó có thể coi rằng","usage":"Nêu sự phản bác thận trọng.","example":"제시된 자료만으로 그 주장이 타당하다고 보기는 어렵습니다. → Chỉ với số liệu nêu ra khó cho rằng lập luận đó thỏa đáng.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-라는 근거","meaning":"bằng chứng rằng","usage":"Dẫn luận cứ.","example":"일부 사례만 있다는 근거로 전체를 일반화할 수는 없습니다. → Không thể khái quát toàn thể chỉ từ vài trường hợp.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["반론","phản biện"],["주장","luận điểm"],["근거","luận cứ"],["타당하다","hợp lý"],["검증하다","kiểm chứng"],["논리","logic"],["오류","sai sót"],["해석하다","diễn giải"],["판단하다","đánh giá"],["가정","giả định"]],"samples":[{"ko":"제시된 자료만으로 그 주장이 타당하다고 보기는 어렵습니다.","vi":"Chỉ với số liệu nêu ra khó cho rằng lập luận đó thỏa đáng."},{"ko":"일부 사례만 있다는 근거로 전체를 일반화할 수는 없습니다.","vi":"Không thể khái quát toàn thể chỉ từ vài trường hợp."},{"ko":"상대방의 문제 제기를 인정하면서도 다른 설명을 제시할 수 있습니다.","vi":"Có thể thừa nhận vấn đề đối phương nêu mà vẫn đưa ra giải thích khác."},{"ko":"논쟁에서는 표현의 강도보다 근거의 정확성이 더 중요합니다.","vi":"Trong tranh luận, độ chính xác bằng chứng quan trọng hơn lời lẽ mạnh."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":5,"bai":15,"title":"Diễn thuyết về thay đổi xã hội","grammar":[{"formula":"-를 계기로","meaning":"nhân dịp / qua sự kiện","usage":"Nêu sự kiện khơi mào thay đổi.","example":"이번 경험을 계기로 사회 변화의 원인을 다시 생각하게 되었습니다. → Nhờ trải nghiệm này tôi suy ngẫm lại nguyên nhân thay đổi xã hội.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-도록 하다","meaning":"cố gắng / bảo đảm làm","usage":"Diễn tả sự sắp xếp hoặc yêu cầu thực hiện.","example":"다양한 세대의 관점이 논의에 반영되도록 해야 합니다. → Cần phản ánh góc nhìn các thế hệ khác nhau vào thảo luận.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["사회","xã hội"],["변화","thay đổi"],["원인","nguyên nhân"],["계기","cơ hội/dịp"],["참여","tham gia"],["공동체","cộng đồng"],["정책","chính sách"],["발전","phát triển"],["노력","nỗ lực"],["연대하다","đoàn kết"]],"samples":[{"ko":"이번 경험을 계기로 사회 변화의 원인을 다시 생각하게 되었습니다.","vi":"Nhờ trải nghiệm này tôi suy ngẫm lại nguyên nhân thay đổi xã hội."},{"ko":"다양한 세대의 관점이 논의에 반영되도록 해야 합니다.","vi":"Cần phản ánh góc nhìn các thế hệ khác nhau vào thảo luận."},{"ko":"변화가 모두에게 같은 기회를 제공하는 것은 아닙니다.","vi":"Thay đổi không mang lại cơ hội như nhau cho mọi người."},{"ko":"공동체의 신뢰를 높이는 방향으로 정책을 설계해야 합니다.","vi":"Nên thiết kế chính sách hướng đến tăng niềm tin cộng đồng."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":6,"bai":1,"title":"Bảo vệ đề cương nghiên cứu","grammar":[{"formula":"-에 입각하여","meaning":"dựa trên","usage":"Nêu nguyên tắc hoặc cơ sở phân tích.","example":"본 연구는 장기적인 관찰 결과에 입각하여 가설을 검토하는 데 목적이 있습니다. → Nghiên cứu này nhằm kiểm tra giả thuyết dựa trên quan sát dài hạn.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-는 데 목적이 있다","meaning":"nhằm mục đích","usage":"Nêu mục tiêu chính của hành động.","example":"선행 연구와 비교해 분석 틀을 확장했다는 점에서 의의가 있습니다. → Ý nghĩa ở việc mở rộng khung phân tích so với nghiên cứu trước.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["연구","nghiên cứu"],["가설","giả thuyết"],["검토하다","xem xét"],["관찰","quan sát"],["분석","phân tích"],["표본","mẫu nghiên cứu"],["대표성","tính đại diện"],["검증하다","kiểm chứng"],["한계","giới hạn"],["결론","kết luận"]],"samples":[{"ko":"본 연구는 장기적인 관찰 결과에 입각하여 가설을 검토하는 데 목적이 있습니다.","vi":"Nghiên cứu này nhằm kiểm tra giả thuyết dựa trên quan sát dài hạn."},{"ko":"선행 연구와 비교해 분석 틀을 확장했다는 점에서 의의가 있습니다.","vi":"Ý nghĩa ở việc mở rộng khung phân tích so với nghiên cứu trước."},{"ko":"표본의 대표성에 관한 우려를 고려해 추가 검증을 실시하겠습니다.","vi":"Tôi sẽ kiểm chứng thêm xét lo ngại về tính đại diện của mẫu."},{"ko":"결론을 일반화하는 과정에서는 연구의 한계를 명확히 밝히겠습니다.","vi":"Khi khái quát kết luận tôi sẽ nêu rõ giới hạn nghiên cứu."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":6,"bai":2,"title":"Phân tích chính sách sâu","grammar":[{"formula":"-에 비추어","meaning":"xét theo / soi chiếu","usage":"Nêu tiêu chí đánh giá.","example":"정책의 효과는 경제적 지표뿐 아니라 사회적 신뢰에 비추어 평가해야 합니다. → Hiệu quả chính sách cần đánh giá theo cả niềm tin xã hội chứ không chỉ chỉ số kinh tế.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-과/와 맞물리다","meaning":"gắn chặt với","usage":"Nói hai yếu tố tương tác nhau.","example":"제도 변화는 기존의 이해관계와 맞물리면서 예상하지 못한 결과를 낳기도 합니다. → Thay đổi thể chế tương tác lợi ích sẵn có và có thể tạo hệ quả ngoài dự kiến.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["정책","chính sách"],["효과","hiệu quả"],["지표","chỉ số"],["평가하다","đánh giá"],["신뢰","niềm tin"],["이해관계","quan hệ lợi ích"],["수혜","được hưởng lợi"],["분배","phân phối"],["조정하다","điều chỉnh"],["보완하다","bổ sung"]],"samples":[{"ko":"정책의 효과는 경제적 지표뿐 아니라 사회적 신뢰에 비추어 평가해야 합니다.","vi":"Hiệu quả chính sách cần đánh giá theo cả niềm tin xã hội chứ không chỉ chỉ số kinh tế."},{"ko":"제도 변화는 기존의 이해관계와 맞물리면서 예상하지 못한 결과를 낳기도 합니다.","vi":"Thay đổi thể chế tương tác lợi ích sẵn có và có thể tạo hệ quả ngoài dự kiến."},{"ko":"수혜 집단과 부담 집단을 구분하면 분배 효과를 더 정확히 이해할 수 있습니다.","vi":"Phân tách nhóm hưởng lợi và chịu gánh nặng giúp hiểu hiệu ứng phân phối chính xác hơn."},{"ko":"평가 결과에 따라 보완 정책을 유연하게 조정할 필요가 있습니다.","vi":"Cần linh hoạt điều chỉnh chính sách bổ trợ theo kết quả đánh giá."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":6,"bai":3,"title":"Hòa giải đa văn hóa","grammar":[{"formula":"-을/를 매개로","meaning":"thông qua","usage":"Nêu phương tiện trung gian kết nối.","example":"갈등을 중재할 때는 공동의 목표를 매개로 대화를 시작하는 것이 효과적입니다. → Khi hòa giải, mở đầu đối thoại qua mục tiêu chung là hiệu quả.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-을/를 존중하되","meaning":"tôn trọng ... nhưng","usage":"Nhấn mạnh sự nhượng bộ kèm điều kiện.","example":"각자의 문화적 배경을 존중하되 책임 소재는 분명히 해야 합니다. → Tôn trọng nền văn hóa mỗi bên nhưng cần làm rõ trách nhiệm.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["문화","văn hóa"],["갈등","xung đột"],["중재하다","hòa giải"],["존중하다","tôn trọng"],["오해","hiểu lầm"],["배경","bối cảnh"],["협의","thảo luận"],["원칙","nguyên tắc"],["책임","trách nhiệm"],["합의하다","thống nhất"]],"samples":[{"ko":"갈등을 중재할 때는 공동의 목표를 매개로 대화를 시작하는 것이 효과적입니다.","vi":"Khi hòa giải, mở đầu đối thoại qua mục tiêu chung là hiệu quả."},{"ko":"각자의 문화적 배경을 존중하되 책임 소재는 분명히 해야 합니다.","vi":"Tôn trọng nền văn hóa mỗi bên nhưng cần làm rõ trách nhiệm."},{"ko":"오해의 원인을 개인의 태도만으로 환원해서는 안 됩니다.","vi":"Không nên quy nguyên nhân hiểu lầm chỉ về thái độ cá nhân."},{"ko":"지속적인 협의를 통해 모두가 수용할 수 있는 원칙을 마련하겠습니다.","vi":"Qua thảo luận liên tục sẽ xây dựng nguyên tắc các bên chấp nhận."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":6,"bai":4,"title":"Đọc phê phán số liệu","grammar":[{"formula":"-라고 해서","meaning":"không phải cứ ... là","usage":"Phủ nhận suy luận tự động từ điều kiện.","example":"두 변수가 함께 변한다고 해서 직접적인 인과관계가 성립하는 것은 아닙니다. → Hai biến cùng thay đổi không có nghĩa tồn tại quan hệ nhân quả trực tiếp.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-을/를 뒷받침하다","meaning":"ủng hộ / củng cố","usage":"Nêu căn cứ hỗ trợ luận điểm.","example":"추가 분석이 주장을 뒷받침하는지 확인할 필요가 있습니다. → Cần xem phân tích bổ sung có ủng hộ luận điểm không.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["자료","dữ liệu"],["변수","biến số"],["인과관계","quan hệ nhân quả"],["상관관계","tương quan"],["검증하다","kiểm chứng"],["추론하다","suy luận"],["근거","căn cứ"],["분석하다","phân tích"],["해석하다","diễn giải"],["통계","thống kê"]],"samples":[{"ko":"두 변수가 함께 변한다고 해서 직접적인 인과관계가 성립하는 것은 아닙니다.","vi":"Hai biến cùng thay đổi không có nghĩa tồn tại quan hệ nhân quả trực tiếp."},{"ko":"추가 분석이 주장을 뒷받침하는지 확인할 필요가 있습니다.","vi":"Cần xem phân tích bổ sung có ủng hộ luận điểm không."},{"ko":"자료가 수집된 맥락을 무시하면 해석이 왜곡될 수 있습니다.","vi":"Bỏ qua bối cảnh thu thập dữ liệu có thể làm sai lệch diễn giải."},{"ko":"불확실성을 인정하는 태도가 오히려 논의의 신뢰성을 높입니다.","vi":"Thừa nhận bất định lại nâng độ tin cậy thảo luận."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":6,"bai":5,"title":"Thương lượng phức hợp","grammar":[{"formula":"-을/를 조건으로","meaning":"với điều kiện","usage":"Chỉ điều kiện trao đổi.","example":"일정 조정을 조건으로 추가 자원을 제공하는 방안을 검토할 수 있습니다. → Có thể cân nhắc hỗ trợ nguồn lực thêm với điều kiện điều chỉnh lịch.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-을/를 감수하다","meaning":"chấp nhận chịu","usage":"Nêu sự chấp nhận rủi ro hoặc thiệt hại.","example":"단기적인 손실을 감수하더라도 장기적 신뢰를 지키는 것이 중요합니다. → Dù chịu tổn thất ngắn hạn, giữ niềm tin dài hạn vẫn quan trọng.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["협상","đàm phán"],["조건","điều kiện"],["자원","nguồn lực"],["일정","lịch trình"],["조정하다","điều chỉnh"],["양보하다","nhượng bộ"],["제안","đề xuất"],["합의","thỏa thuận"],["감수하다","chấp nhận chịu"],["전략","chiến lược"]],"samples":[{"ko":"일정 조정을 조건으로 추가 자원을 제공하는 방안을 검토할 수 있습니다.","vi":"Có thể cân nhắc hỗ trợ nguồn lực thêm với điều kiện điều chỉnh lịch."},{"ko":"단기적인 손실을 감수하더라도 장기적 신뢰를 지키는 것이 중요합니다.","vi":"Dù chịu tổn thất ngắn hạn, giữ niềm tin dài hạn vẫn quan trọng."},{"ko":"각 이해관계자의 우선순위를 파악해야 현실적인 합의가 가능합니다.","vi":"Phải hiểu ưu tiên của các bên mới có thỏa thuận khả thi."},{"ko":"합의 이후의 점검 절차까지 구체적으로 명시하겠습니다.","vi":"Tôi sẽ nêu cụ thể cả quy trình theo dõi sau thỏa thuận."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":6,"bai":6,"title":"Phân tích ngụy biện","grammar":[{"formula":"-에 지나지 않다","meaning":"chẳng qua chỉ là","usage":"Giới hạn bản chất sự việc.","example":"개별 사례를 전체의 경향으로 해석하는 것은 성급한 일반화에 지나지 않습니다. → Diễn giải một trường hợp thành xu hướng chung chỉ là khái quát vội.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-을/를 혼동하다","meaning":"nhầm lẫn","usage":"Nêu việc đánh đồng hai khái niệm.","example":"상관관계와 인과관계를 혼동하면 잘못된 결론에 도달하기 쉽습니다. → Nhầm tương quan và nhân quả dễ đưa tới kết luận sai.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["논리","logic"],["오류","sai lầm"],["일반화","khái quát hóa"],["사례","trường hợp"],["경향","xu hướng"],["혼동하다","nhầm lẫn"],["반박하다","bác bỏ"],["주장","luận điểm"],["근거","luận cứ"],["추론하다","suy luận"]],"samples":[{"ko":"개별 사례를 전체의 경향으로 해석하는 것은 성급한 일반화에 지나지 않습니다.","vi":"Diễn giải một trường hợp thành xu hướng chung chỉ là khái quát vội."},{"ko":"상관관계와 인과관계를 혼동하면 잘못된 결론에 도달하기 쉽습니다.","vi":"Nhầm tương quan và nhân quả dễ đưa tới kết luận sai."},{"ko":"상대 주장의 의도를 추측하기보다 논리 구조를 검토해야 합니다.","vi":"Nên xem cấu trúc logic thay vì đoán ý đồ bên kia."},{"ko":"반론을 제시할 때는 대안적인 설명도 함께 제안하겠습니다.","vi":"Khi phản biện tôi cũng sẽ đề xuất giải thích thay thế."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":6,"bai":7,"title":"Đạo đức nghiên cứu","grammar":[{"formula":"-를 명분으로","meaning":"lấy ... làm danh nghĩa","usage":"Nêu lý do được viện dẫn.","example":"연구 성과를 명분으로 참여자의 동의를 생략해서는 안 됩니다. → Không được bỏ qua đồng ý của người tham gia lấy cớ vì kết quả nghiên cứu.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-을/를 전제하다","meaning":"giả định trước","usage":"Nêu điều kiện nền tảng được mặc định.","example":"개인정보 보호를 전제하지 않은 분석은 정당성을 얻기 어렵습니다. → Phân tích không đặt bảo vệ dữ liệu cá nhân làm tiền đề khó có tính chính đáng.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["윤리","đạo đức"],["연구","nghiên cứu"],["동의","sự đồng ý"],["참여자","người tham gia"],["보호하다","bảo vệ"],["성과","kết quả"],["명분","danh nghĩa"],["절차","thủ tục"],["책임","trách nhiệm"],["전제","tiền đề"]],"samples":[{"ko":"연구 성과를 명분으로 참여자의 동의를 생략해서는 안 됩니다.","vi":"Không được bỏ qua đồng ý của người tham gia lấy cớ vì kết quả nghiên cứu."},{"ko":"개인정보 보호를 전제하지 않은 분석은 정당성을 얻기 어렵습니다.","vi":"Phân tích không đặt bảo vệ dữ liệu cá nhân làm tiền đề khó có tính chính đáng."},{"ko":"이해 충돌이 발생할 가능성은 사전에 공개해야 합니다.","vi":"Khả năng xung đột lợi ích cần công khai trước."},{"ko":"윤리적 기준을 지키는 일은 연구의 신뢰성을 확보하는 과정입니다.","vi":"Tuân thủ đạo đức là quá trình bảo đảm độ tin cậy nghiên cứu."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":6,"bai":8,"title":"Diễn ngôn và sắc thái","grammar":[{"formula":"-기 십상이다","meaning":"rất dễ có kết quả xấu","usage":"Diễn tả điều dễ xảy ra, thường tiêu cực.","example":"직접적인 비판은 상황에 따라 관계를 악화시키기 십상입니다. → Phê bình trực diện tùy tình huống dễ làm xấu quan hệ.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-고자 하다","meaning":"muốn / nhằm","usage":"Nêu ý định trang trọng.","example":"제 의견을 강요하기보다 공동의 이해를 넓히고자 합니다. → Tôi muốn mở rộng hiểu biết chung hơn là áp đặt quan điểm.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["담화","diễn ngôn"],["맥락","bối cảnh"],["뉘앙스","sắc thái"],["비판","phê bình"],["관계","mối quan hệ"],["오해","hiểu nhầm"],["표현","biểu đạt"],["완곡하다","nói giảm nói tránh"],["의도","ý định"],["소통","giao tiếp"]],"samples":[{"ko":"직접적인 비판은 상황에 따라 관계를 악화시키기 십상입니다.","vi":"Phê bình trực diện tùy tình huống dễ làm xấu quan hệ."},{"ko":"제 의견을 강요하기보다 공동의 이해를 넓히고자 합니다.","vi":"Tôi muốn mở rộng hiểu biết chung hơn là áp đặt quan điểm."},{"ko":"동일한 사실도 어떤 표현을 택하느냐에 따라 다르게 받아들여집니다.","vi":"Cùng một sự thật nhưng được tiếp nhận khác nhau theo cách diễn đạt."},{"ko":"상대의 체면을 고려하면서도 핵심 메시지는 분명하게 전달해야 합니다.","vi":"Cần truyền đạt ý chính rõ ràng nhưng vẫn giữ thể diện cho đối phương."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":6,"bai":9,"title":"Xử lý khủng hoảng truyền thông","grammar":[{"formula":"-을/를 계기로","meaning":"nhân dịp / qua sự kiện","usage":"Nêu sự kiện khơi mào thay đổi.","example":"이번 사태를 계기로 내부 점검 체계를 전면 재검토하겠습니다. → Nhân sự việc lần này chúng tôi sẽ rà soát toàn diện hệ thống kiểm tra nội bộ.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-에 대비하여","meaning":"để chuẩn bị đối phó","usage":"Chỉ mục đích phòng bị.","example":"추가 피해에 대비하여 관련 정보를 투명하게 공개하겠습니다. → Để phòng thiệt hại thêm, chúng tôi sẽ công khai thông tin minh bạch.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["위기","khủng hoảng"],["언론","báo chí"],["대응하다","ứng phó"],["사태","sự cố"],["점검하다","kiểm tra"],["체계","hệ thống"],["신뢰","niềm tin"],["공개하다","công khai"],["책임","trách nhiệm"],["재검토하다","xem xét lại"]],"samples":[{"ko":"이번 사태를 계기로 내부 점검 체계를 전면 재검토하겠습니다.","vi":"Nhân sự việc lần này chúng tôi sẽ rà soát toàn diện hệ thống kiểm tra nội bộ."},{"ko":"추가 피해에 대비하여 관련 정보를 투명하게 공개하겠습니다.","vi":"Để phòng thiệt hại thêm, chúng tôi sẽ công khai thông tin minh bạch."},{"ko":"원인 규명 이전에 확인되지 않은 내용을 단정하지 않겠습니다.","vi":"Trước khi xác minh nguyên nhân chúng tôi không khẳng định thông tin chưa chắc chắn."},{"ko":"이해당사자의 우려를 경청하고 시정 계획을 발표하겠습니다.","vi":"Chúng tôi sẽ lắng nghe lo ngại của các bên và công bố kế hoạch khắc phục."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":6,"bai":10,"title":"Bình luận văn học","grammar":[{"formula":"-에 투영되다","meaning":"được phản chiếu vào","usage":"Nêu ý nghĩa biểu trưng trong tác phẩm.","example":"작품 속 공간에는 인물의 불안과 시대적 상황이 함께 투영되어 있습니다. → Không gian trong tác phẩm phản ánh cả nỗi bất an nhân vật và thời đại.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-을/를 드러내다","meaning":"bộc lộ","usage":"Nêu đặc điểm hoặc cảm xúc.","example":"반복되는 이미지가 주인공의 내적 갈등을 드러낸다고 해석할 수 있습니다. → Có thể diễn giải hình ảnh lặp lại bộc lộ mâu thuẫn nội tâm nhân vật.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["문학","văn học"],["작품","tác phẩm"],["인물","nhân vật"],["공간","không gian"],["투영되다","phản chiếu"],["상징","biểu tượng"],["불안","lo âu"],["시대","thời đại"],["해석하다","diễn giải"],["서술하다","trần thuật"]],"samples":[{"ko":"작품 속 공간에는 인물의 불안과 시대적 상황이 함께 투영되어 있습니다.","vi":"Không gian trong tác phẩm phản ánh cả nỗi bất an nhân vật và thời đại."},{"ko":"반복되는 이미지가 주인공의 내적 갈등을 드러낸다고 해석할 수 있습니다.","vi":"Có thể diễn giải hình ảnh lặp lại bộc lộ mâu thuẫn nội tâm nhân vật."},{"ko":"해석의 설득력을 높이려면 구체적인 문장에 근거해야 합니다.","vi":"Muốn tăng sức thuyết phục cần dựa trên câu văn cụ thể."},{"ko":"독자의 경험에 따라 작품의 의미가 다르게 형성될 수 있습니다.","vi":"Ý nghĩa tác phẩm có thể hình thành khác nhau theo trải nghiệm người đọc."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":6,"bai":11,"title":"Đánh giá chiến lược giáo dục","grammar":[{"formula":"-에 근거하다","meaning":"dựa trên","usage":"Chỉ căn cứ phán đoán.","example":"개편안의 타당성은 단기 성과보다 장기적인 학습 지표에 근거해 판단해야 합니다. → Tính hợp lý cải cách phải dựa vào chỉ số học tập dài hạn thay vì kết quả ngắn hạn.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-과/와 상충하다","meaning":"mâu thuẫn với","usage":"Chỉ sự xung đột giữa nguyên tắc.","example":"효율성 목표가 교육의 공정성과 상충할 가능성도 검토해야 합니다. → Cần xét khả năng mục tiêu hiệu quả xung đột với công bằng giáo dục.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["전략","chiến lược"],["교육","giáo dục"],["성과","thành quả"],["지표","chỉ số"],["개편안","phương án cải tổ"],["근거","căn cứ"],["검토하다","xem xét"],["상충하다","mâu thuẫn"],["타당성","tính hợp lý"],["평가하다","đánh giá"]],"samples":[{"ko":"개편안의 타당성은 단기 성과보다 장기적인 학습 지표에 근거해 판단해야 합니다.","vi":"Tính hợp lý cải cách phải dựa vào chỉ số học tập dài hạn thay vì kết quả ngắn hạn."},{"ko":"효율성 목표가 교육의 공정성과 상충할 가능성도 검토해야 합니다.","vi":"Cần xét khả năng mục tiêu hiệu quả xung đột với công bằng giáo dục."},{"ko":"다양한 집단의 경험을 반영하지 않으면 정책의 수용성이 떨어질 수 있습니다.","vi":"Không phản ánh trải nghiệm nhiều nhóm có thể giảm mức chấp nhận chính sách."},{"ko":"시범 사업의 결과를 토대로 단계적으로 확대할 것을 권고합니다.","vi":"Tôi khuyến nghị mở rộng theo giai đoạn dựa trên kết quả thí điểm."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":6,"bai":12,"title":"Vai trò lãnh đạo","grammar":[{"formula":"-은/는커녕","meaning":"đừng nói ... đến cả ... cũng không","usage":"Nhấn mạnh phủ định mạnh hơn dự kiến.","example":"성과만 강조해서는 신뢰는커녕 구성원의 자발적인 참여도 얻기 어렵습니다. → Chỉ nhấn mạnh thành tích thì khó nhận cả niềm tin lẫn sự tự nguyện.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-에 달려 있다","meaning":"phụ thuộc vào","usage":"Nêu yếu tố quyết định.","example":"리더십의 성패는 책임을 나누는 방식에 달려 있습니다. → Thành bại lãnh đạo phụ thuộc cách chia sẻ trách nhiệm.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["리더십","năng lực lãnh đạo"],["신뢰","niềm tin"],["성과","kết quả"],["구성원","thành viên"],["참여","sự tham gia"],["조직","tổ chức"],["책임","trách nhiệm"],["자발적","tự nguyện"],["협력하다","hợp tác"],["존중하다","tôn trọng"]],"samples":[{"ko":"성과만 강조해서는 신뢰는커녕 구성원의 자발적인 참여도 얻기 어렵습니다.","vi":"Chỉ nhấn mạnh thành tích thì khó nhận cả niềm tin lẫn sự tự nguyện."},{"ko":"리더십의 성패는 책임을 나누는 방식에 달려 있습니다.","vi":"Thành bại lãnh đạo phụ thuộc cách chia sẻ trách nhiệm."},{"ko":"의사결정 과정의 투명성이 조직 문화의 기반이 됩니다.","vi":"Minh bạch quá trình quyết định là nền tảng văn hóa tổ chức."},{"ko":"실패의 원인을 개인에게 전가하지 않는 태도가 필요합니다.","vi":"Cần thái độ không đổ lỗi thất bại cho cá nhân."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":6,"bai":13,"title":"Công nghệ và công bằng","grammar":[{"formula":"-을/를 전제로 하다","meaning":"lấy ... làm tiền đề","usage":"Nêu cơ sở giả định.","example":"디지털 전환은 모든 사람이 기술에 접근할 수 있다는 전제를 경계해야 합니다. → Chuyển đổi số cần tránh giả định ai cũng tiếp cận được công nghệ.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-을/를 간과하다","meaning":"bỏ qua","usage":"Nêu việc không xem xét đủ yếu tố.","example":"취약 집단의 경험을 간과하면 새로운 불평등이 나타날 수 있습니다. → Nếu xem nhẹ nhóm yếu thế có thể xuất hiện bất bình đẳng mới.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["기술","công nghệ"],["공정성","tính công bằng"],["전환","chuyển đổi"],["접근성","khả năng tiếp cận"],["격차","khoảng cách"],["전제","tiền đề"],["간과하다","bỏ qua"],["보장하다","bảo đảm"],["사회","xã hội"],["권리","quyền lợi"]],"samples":[{"ko":"디지털 전환은 모든 사람이 기술에 접근할 수 있다는 전제를 경계해야 합니다.","vi":"Chuyển đổi số cần tránh giả định ai cũng tiếp cận được công nghệ."},{"ko":"취약 집단의 경험을 간과하면 새로운 불평등이 나타날 수 있습니다.","vi":"Nếu xem nhẹ nhóm yếu thế có thể xuất hiện bất bình đẳng mới."},{"ko":"효율성 지표뿐 아니라 실질적인 접근성을 평가해야 합니다.","vi":"Cần đánh giá tiếp cận thực chất chứ không chỉ chỉ số hiệu quả."},{"ko":"설계 단계부터 다양한 사용자의 의견을 반영할 필요가 있습니다.","vi":"Cần phản ánh ý kiến nhiều người dùng ngay từ bước thiết kế."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":6,"bai":14,"title":"Tổng kết bài học từ thất bại","grammar":[{"formula":"-음을 인정하다","meaning":"thừa nhận rằng","usage":"Danh từ hóa để công nhận một thực tế.","example":"초기 판단에 한계가 있었음을 인정하는 것이 개선의 출발점입니다. → Thừa nhận hạn chế của đánh giá ban đầu là điểm khởi đầu cải tiến.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-을/를 토대로","meaning":"dựa trên","usage":"Nêu cơ sở phát triển lập luận.","example":"실패 원인을 개인적 실수로만 환원하지 않겠습니다. → Tôi không quy nguyên nhân thất bại chỉ cho sai sót cá nhân.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["실패","thất bại"],["교훈","bài học kinh nghiệm"],["판단","phán đoán"],["한계","hạn chế"],["인정하다","thừa nhận"],["개선하다","cải thiện"],["과정","quá trình"],["평가하다","đánh giá"],["기록","ghi chép"],["성찰하다","tự nhìn nhận"]],"samples":[{"ko":"초기 판단에 한계가 있었음을 인정하는 것이 개선의 출발점입니다.","vi":"Thừa nhận hạn chế của đánh giá ban đầu là điểm khởi đầu cải tiến."},{"ko":"실패 원인을 개인적 실수로만 환원하지 않겠습니다.","vi":"Tôi không quy nguyên nhân thất bại chỉ cho sai sót cá nhân."},{"ko":"분석 결과를 토대로 향후 절차를 체계적으로 보완하겠습니다.","vi":"Dựa vào phân tích tôi sẽ bổ sung có hệ thống quy trình tương lai."},{"ko":"경험에서 얻은 교훈을 조직 차원에서 공유할 필요가 있습니다.","vi":"Cần chia sẻ bài học kinh nghiệm ở cấp tổ chức."}],"source":"mrlee-roadmap-and-original-editorial"},{"cap":6,"bai":15,"title":"Bảo vệ quan điểm cuối khóa","grammar":[{"formula":"-에 반하여","meaning":"trái với","usage":"Nêu điều xảy ra trái dự đoán.","example":"일반적인 예상에 반하여 조사 결과는 다른 방향의 변화를 보여 주었습니다. → Trái dự đoán thông thường, kết quả khảo sát cho thấy hướng thay đổi khác.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."},{"formula":"-음을 시사하다","meaning":"hàm ý rằng","usage":"Nêu kết luận gián tiếp từ dấu hiệu.","example":"이러한 차이는 기존 설명의 한계를 시사한다고 볼 수 있습니다. → Khác biệt này có thể chỉ ra hạn chế của cách giải thích trước.","exampleSource":"roadmap-sample","reviewNote":"Câu minh họa lấy từ ngân hàng mẫu trong bài; cần kiểm tra khớp cấu trúc."}],"vocab":[["관점","quan điểm"],["반론","phản biện"],["주장","luận điểm"],["연구","nghiên cứu"],["결론","kết luận"],["예상","dự đoán"],["시사하다","hàm ý"],["검증하다","kiểm chứng"],["근거","căn cứ"],["발표하다","trình bày"]],"samples":[{"ko":"일반적인 예상에 반하여 조사 결과는 다른 방향의 변화를 보여 주었습니다.","vi":"Trái dự đoán thông thường, kết quả khảo sát cho thấy hướng thay đổi khác."},{"ko":"이러한 차이는 기존 설명의 한계를 시사한다고 볼 수 있습니다.","vi":"Khác biệt này có thể chỉ ra hạn chế của cách giải thích trước."},{"ko":"저는 두 가지 대안 중 실행 가능성이 높은 방안을 제안하고자 합니다.","vi":"Tôi muốn đề xuất phương án khả thi hơn trong hai lựa chọn."},{"ko":"제 발표의 결론은 추가 검증의 필요성을 부정하지 않는다는 점을 강조합니다.","vi":"Tôi nhấn mạnh kết luận không phủ nhận nhu cầu kiểm chứng thêm."}],"source":"mrlee-roadmap-and-original-editorial"}];
